INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p987113-me201', 'stk-user5216', 'ME 201', 'info', '{"desc": "**بسم الله الرحمن الرحيم**جودة المقرر بشكل عام : ممتاز وشيق جدا\n\n**المواضيع التي يغطيها المقرر : قوانين السرعه والتسارع + التصادم + الدوران + conservation of momentum and impulse **\n\nالكتاب المستخدم للمقرر : ممتاز جدا وانصح بالاعتماد عليه\n\nالأسئلة والأمثلة المستخدمة في المقرر : كافية جدا وسهلة الفهم\n\nطريقة دراسة المقرر :\n1 - قراءة الكتاب وفهم القوانين\n2 - فهم الامثلة الي موجوده في الكتاب واعادة حلها\n3 - حل Fundamental Problems الي بنهاية كل سكشن\n4 - حل اسئلة الهومورك والاسئلة المشابهه\n5 - الاولد اقزامز (خصوصا قبل الفاينل ) 🙂\n\nالمادة ممتعه والكتاب كافي ووافي وبشكل عام خذها قاعدة\nكتب hibbeler الافضل من ناحية الشرح وكثرة الامثله والتمارين\n\n, وبالتوفيق ,", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201-dynamics/120731/2", "user": "user5216", "ts": 1329315685000, "tid": 120731, "pn": 2}}', 1329315685000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1012489-me201', 'stk-_hlali', 'ME 201', 'info', '{"desc": "جودة المقرر بشكل عام مفيد جدا.\nالمواضيع التي يغطيها المقررمثل ماقال اخوي الرقمي.\nالكتاب المستخدم للمقرر الكتاب ممتاز وكعادة كتب هيبلر كلها ممتازه ولو اني ماحب هالنوع من المواد لاني مهما ذاكرت اجيب العيد بالاختبار.ولكن هذا عيب فيني مو من الكتاب.\nالأسئلة والأمثلة المستخدمة في المقرر كافية جدا وواضحة.\nمدى فائدته في الناحية التطبيقيةالماده واقعيه يعني كلها اشياء موجود في ارض الواقع\nطرق دراسة المقرر.\n\nاستخدام الكتاب للمذاكرة لانه سهل الفهم وعدم المذاكرة من السلايدات.\n\nحل امثلة الكتاب وفهمها على الاقل قبل الدخول لاي ميجر او كويز .\n\nحل اسئلة الهوم وورك بفهم وبدون تسليك كثير لانك بتجيب العيد اذا قمت تسلك كثير 🤠.\n\nللي راغب في قريد عالي يحل جميع الاسئلة الي بنهاية كل تشابتر.\n\nالكورس بشكل عام لاهو بصعب ولا هو بسهل يعني متوسط بشكل عام .\n\nوبالتوفيق للجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201-dynamics/120731/4", "user": "_HLALI", "ts": 1332169232000, "tid": 120731, "pn": 4}}', 1332169232000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1074914-me201', 'stk-ibra1991', 'ME 201', 'info', '{"desc": "تجربتي مع me 201 سمستر 112 عند القحطاني ولله الحمد اخذت B+\nمنهج المادة= مثل ماقالوا الإخوان إلا اني بزيد عليهم ان المنهج قسمين, الاول عن الحركة المنتظيمة (الكتلة تنتقل كنقطة واحدة او جسم واحد يعني جميع اجزاء الكتلة تنتقل بنفس السرعة) تستخدم القوانين الي ذكروها الشباب ,الثاني إعادة للقسم الاول لكن يتكلم عن حركة الكتلة تكون غير منتظمة ( يعني كل جزء بالكتلة له سرعنه وخواصه) يزيدون بعض القوانين .\n-الاختبار الاول= يكون عن القسم الاول بحكم ان المنهج سهل راح يكون الاختبار سهل واحرص عليه ولا تفوت السهوله (انا اخذت فيه 99 وخبصت بالباقي لكن طلعت بقريد كويس )\n-الختبار الثاني = كان بين القسمين وكان صعب لدجة ان اغلب الطاب جابوا 50%\n-الفاينال = كان عن القسم الثاني ,جابوا اختيارات وفيه يمكن سوال ريتين الاختبار كان متوسط .\nالكوزات = عند القحطاني من الهوموورك\nطريقة المذاكرة = حاول تحصل على السليوشن مانول من المنتدى او التراكر وتحل الاسئلة وقب كذا تحل اسئلة الامثلة واسئلة Fundamental Problem وحاول تعمل ملخص لكل شابتر لان اسئلة الإختبارات كل شابتر تكون عنه اسئلة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201-dynamics/120731/5", "user": "ibra1991", "ts": 1343902313000, "tid": 120731, "pn": 5}}', 1343902313000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1228968-me201', 'stk-s2010xxxxx', 'ME 201', 'info', '{"desc": "جودة المقرر بشكل عام: ممتاز\nالكتاب المستخدم للمقرر : ممتاز جدا\nالأسئلة والأمثلة المستخدمة في المقرر : ممتازه\nمدى فائدته في الناحية التطبيقية : ملحوظه وبشكل كبير\n\nالماده تعتبر صعبه وتحتاج مجهود وحل تمارين كثير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201-dynamics/120731/6", "user": "s2010xxxxx", "ts": 1369689503000, "tid": 120731, "pn": 6}}', 1369689503000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1320572-me201', 'stk-user2352', 'ME 201', 'info', '{"desc": "http://www.learnerstv.com/Free-Engineering-Video-lectures-ltv069-Page1.htm\nhttp://www.learnerstv.com/Free-Engineering-Video-lectures-ltv070-Page1.htm\nشروحات أونلاين فيديو مفيدة لأغلب محتى الكورس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201-dynamics/120731/9", "user": "user2352", "ts": 1390042547000, "tid": 120731, "pn": 9}}', 1390042547000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1381739-me201', 'stk-abo_ali', 'ME 201', 'info', '{"desc": "داينمكس ي داينمكس , وينش الله يقلعش ,\nحبيت ذي الماده بعد ما شفت الــ 309 ههههههههه\n---------------------------------\n\nجودة المقرر بشكل عام\nممتاز 🙂\n\nالمواضيع التي يغطيها المقرر\nما اذكر , خذتها من زمااااااااان\n\nالكتاب المستخدم للمقرر\nجدن ممتاز , -بعد ما شفت النحس حبيتك\n\nالأسئلة والأمثلة المستخدمة في المقرر\nمناسبه للمذاكره وللقريد العالي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201-dynamics/120731/10", "user": "Abo_Ali", "ts": 1403435745000, "tid": 120731, "pn": 10}}', 1403435745000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1494128-me201', 'stk-mohammed_sahwan', 'ME 201', 'info', '{"desc": "بسم الله الرحمن الرحيم\nجودة المقرر بشكل عام:\nمقرر له هيبته ومكانته 😎 يعتمد على حل المسائل الرياضية وأشوف الكونسبت فيه جدا قليل و الكاترة يقضونها في حل المسائل 😐\nالكتاب المستخدم + نظام الدرجات + المواضيع اللي يغطيها المقرر موجودة في المرفق\nمدى فائدته من الناحية التطبيقية:\nأثره قليل لأن مفاهيمه أساسية جدا\nإضافة:\n-الكتاب تحسه كتاب تمارين مليان مسائل. :open_mouth:\n- لترم 172 كان A+ 90-100 و بعدها كل خمس درجات قريد.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201-dynamics/120731/18", "user": "Mohammed_Sahwan", "ts": 1528789347000, "tid": 120731, "pn": 18}}', 1528789347000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1518490-me201', 'stk-mohammed18', 'ME 201', 'info', '{"desc": "TERM 191\n\nالكورس في البدايه سهل بس بعد ميجر ون بدا يصعب شوي.\n\nميجر ١ سهل ودروسه ممتعه.\nميجر ٢ وسط.\nالفاينل اصعب شيء في الكورس لانه يعتمد على كل الي خذيته في الكورس ويحتاج تدريب وفهم خاصة شابتر ١٦ و ١٩.\n\nالكورس بشكل عام يعتبر متوسط الصعوبه بس لاتسحب عليه لان صعب تذاكر في وقت قصير الماده تحتاج براكتس شوي وفهم ووقت.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201-dynamics/120731/19", "user": "Mohammed18", "ts": 1577749944000, "tid": 120731, "pn": 19}}', 1577749944000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1522392-me201', 'stk-nasalmz', 'ME 201', 'info', '{"desc": "term 192\n\nالكورس طبعا يغدر فيك اذا كنت ساحب عليه\nيجيك بالبداية تافه اشياء فزكس 101 ثم سبحان الله يكبس كبس مش طبيعي.\n\nكالعادة هبلر انفض الكتاب وحل بيديك ورجليك عشان تثبت المعلومة وحل كم من اولد اقزام ان حصل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201-dynamics/120731/20", "user": "Nasalmz", "ts": 1590429745000, "tid": 120731, "pn": 20}}', 1590429745000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1527204-me201', 'stk-abofordan2004', 'ME 201', 'info', '{"desc": "TERM 201 ONLINE\n\nمادة ممتازة وبدايتها جدا سهلة عن التسارع الثابت والقوانين اللي اخذتها في الفيزيكس 101 بس انها تصعب من يوم تدخل شابتر 16 تبدا تتعقد فحاول بقدر الامكان انك تجيب فل في الميد واول كويزات لانها ابدا مو مثل مستوى اخر دروس في الصعوبة ف استغلها وارفع درجاتك .\n\nبالنسبة للكونسبت ما ياخذ منك 10-20 دقيقة للفهم والباقي عليك في حل المسائل وركز على ال Odd problems لان اغلب اسألة الكويزات زالاختبارات عليها يا تجي نسخ لصق او مشابهه للفكرة .\n\nبالنسبة للفاينل عندنا كانت الاسأله اللي تنحل بالكتابة مستواها متوسط بينما ال Multiple choice كانت جدا صعبة والافرج فيها كان 2.3 من 10 .\n\nالمادة ايضا فيها بروجكت وبرزنتيشن وكان سهل للامانه فلا تشيل همه.\n\nتوزيع الدرجات :-\nواجبات : 15%\nكويزات : 30% … 15% اتنشن و 15% ريفيو\nميد : 15%\nبروجكت + برزنتيشن : 15%\nفاينل : 25%\n\nملاحظة : تقييمي للمادة في الاون لاين ( زمن كورونا ) ممكن تكون مختلفه جدا في الترم العادي وربما افضل , ف اذا رجعت الدراسة حضوري تجاهل هذا التقييم لانه ما بيفيدك.\n\nبالتوفيق.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201-dynamics/120731/21", "user": "AboFordan2004", "ts": 1608637018000, "tid": 120731, "pn": 21}}', 1608637018000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p918440-me201', 'stk-amat_24', 'ME 201', 'info', '{"desc": "مذاكرة امثلة الكتاب is a must\n\nكنت احلها كلها بنفسي بعدين اقارن حلي مع الكتاب\n\nوالهومووركس حليت نصها بس\n\nاسئلة المياجر كنت اشوفها مقبولة جدا لانه الامثلة كانت ثقيلة\n\nاذا تحل امثلة الكتاب بنفسك اضمنلك على الاقل B+ او A\n\nالامثلة في كتب hibler كنوز حرام انك تفرط فيها\nوالله تتمنى زيها في الكورسات المتقدمة… تصير الاقزامبلز حقتهم حل سريع بدون تفصيل على اساس انك فاهم كيف يفكر اللي يحل 😐", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201/113781/3", "user": "amat_24", "ts": 1318522915000, "tid": 113781, "pn": 3}}', 1318522915000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p841625-me201', 'stk-user3197', 'ME 201', 'info', '{"desc": "سلام عليكم\n\nبالنسبه لوضعك دام ماعندك ولا غياب شد حيلك بالماتيريال واستعد للفاينل زين واتكل ع الله\nوصدقني يمديك ع الـ b\n\nترا اللي راح بالميجرين 45 % يعني باقي اكثر من النص بالهوموركات والكوزات والفاينل\n\nنفترض ان افريج الميجرين 65% يعني 29 من 45\nودرجاتك 45% يعني تقريبا 20 من 45\n\nلو كوزاتك 8 و الهوموركات 9 يصير مجموعك 37 من 65\n\nوالفاينل نقول جبت 80% يصير مجموعك … 65 << اتوقع c او c+\n\n\"لان الافريج بينزل بالفاينل حسب توقعاتي \"\n\nسهله ترا بس انت لاتكدر نفسك وزي ماقلت اتكل على الله\n\nوبالتوفيق … 👍", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me201/107249/4", "user": "user3197", "ts": 1304779504000, "tid": 107249, "pn": 4}}', 1304779504000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1023600-me201', 'stk-user5712', 'ME 201', 'info', '{"desc": "ما أتوقع أن في طالب بيطلع وبيقول أن الإختبار سهل أو حتى متوسط أو حتى فيه أي شيء من السهولة\n\nأنا أعتقد أن كل فقرة في الإختبار صعبة صعبة جداً ، وأتوقع أن الشخص اللي حط الإختبار عنده مشاكل نفسية وحط غضبه فينا\n\nعالعموم أنا لا أعتبر هذا الإختبار بالخصوص مقياس لما درسته ، وأعتبر نفسي فاهم المادة غصباً على المدرس وغصباً على اللي جابه في هالجامعة حتى لو أخذت فيها d", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/2-me201/124361/4", "user": "user5712", "ts": 1334607761000, "tid": 124361, "pn": 4}}', 1334607761000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1023610-me201', 'stk-ahmad1', 'ME 201', 'info', '{"desc": "كفو(يااهم بدراستك)\n\nاوانا بعد اعتبر نفسي فاهم المادة 90%(10% نخليها على جنب عشان نكون صريحين)\nحتى لو يصير الي يصير\nانا ذاكرت الاولد اكزامز\nالاولد اكزامز كانت شئ واختبرنا شئ ثاني\n\nانا كنت متوفع اجيب فل ماراك او فل مارك الا شوي\n\nبس الحين اتمنى اجيب نص الدرجة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/2-me201/124361/6", "user": "AhMaD1", "ts": 1334608590000, "tid": 124361, "pn": 6}}', 1334608590000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1023619-me201', 'stk-omar.a', 'ME 201', 'info', '{"desc": "الحمدلله على كل حال , الاختبار صراحة مخيب للآمال من الدرجة الاولى\n\nيعني ما يكفي ان المنهج دسم , الاختبار يطلع بهذي الصعوبة و فيه تركات كمان !!\n\nالاسئلة حقت الكتاب يالله تنحل , كيف لمن تحط اختبار محيوس زي كذا\n\nالله ييسر , بالتوفيق للجميع في المياجر الباقية\n\n🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/2-me201/124361/8", "user": "Omar.a", "ts": 1334608996000, "tid": 124361, "pn": 8}}', 1334608996000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1023664-me201', 'stk-user7125', 'ME 201', 'info', '{"desc": "يسعد مسآئكم يآشبآب … بالنسبه لطلاب الدكتور خليف … انا ثاني مره اخذ هذي المآدهـ … وبصرآحه آلآسئلهـ صعبهـ جددددآ بالنسبه للسمستر الي رآح ، وعلمآ آني ماكنت مذآكر كثير … بآختصآر السؤآل الثآني نفس السؤآل الي في الي في النوت وتاافه … بس في تررررررررك خلته صععععععب الي هي كيف تطلع الزوآيآ جدآ جدآ صعبهـ … والسؤآل الاول ترك بعد ماسهل لنا الدكتور صار ينبلع … بالنسبه للسؤآل الاخير برضو ترككك …\n\nيعني الاختبآر صعب بصرآحهـ … ماشفنا اي اساله مثل ماقال من النوت … والهوم ورك !!\n\nالله يعين بس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/2-me201/124361/11", "user": "user7125", "ts": 1334612654000, "tid": 124361, "pn": 11}}', 1334612654000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1104376-me201', 'stk-mr-3b0d', 'ME 201', 'info', '{"desc": "الماتيريال تافه جداً\n\nالاختبار كان معقد جداً\n\nاول مرة اشوف سؤال بروجيكتايل موشن واحسه صعب خاصة الهايت ريلاتف تو ار, ومافيه ولا سؤال بالكتاب عليه\n\nالسؤال الثاني\n\nنفس الحكاية احس السؤال حله معقد وطويييل ,كل اسئلة الكتاب يعطيك بالعادة 3 مجاهيل و3 معادلات ومنها تطلع المجاهيل\n\nفي السؤال هذا عطاك 4 معادلات و4 مجاهيل لدرجة ان كان ودي استخدم الماتريكس حقت الماث>>طبعا اذا كانت طريقة حلي صح", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/1-me201/133194/3", "user": "mr-3b0d", "ts": 1349615939000, "tid": 133194, "pn": 3}}', 1349615939000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p999688-me201', 'stk-turky_al-dossary', 'ME 201', 'info', '{"desc": "صراحة لطلاب يحيى خليف ،، الاختبار وااااضح\n\nالسؤال الاول كان عبارة عن الكويز الثاني مع لعبه بسيطة\n\nالسؤال الثاني واضح وضوح الشمس بس كان الترك في ايجاد الزاوية و p لانه فيها لعبه في الراديان\n\nالسؤال الثالث كان من امثلة الكتاب بس الثقل اللي على اليسار مائل وفيه فركشن\n\nالله يوفق الجميع 🙂\n\n🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/1-me201/122254/11", "user": "Turky_Al-Dossary", "ts": 1330810199000, "tid": 122254, "pn": 11}}', 1330810199000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p916814-me201', 'stk-dok116', 'ME 201', 'info', '{"desc": "me 215 سهلة , ركز على مسائل الهوموورك والمسائل مابتكون صعبة أقصى ترك يسووه في المسألة يطلعلك مجهولين وتحل بمعادلتين , لذلك المسائل ان شاء الله مافيها مشاكل\nالمشكلة مع سؤال الاختيارات , بتجي أشياء من بين السطور , انت حاول تقراا بتمعن وتركيز\nإذا انزنقت في وقت المذاكرة ركز على المسائل لانو عليها الويت الأكبر والخيارات في أسوء الحالات بتسوي لها قس:)\n\nme 201 قاعد آخذها حالياً", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201-me-216/113652/2", "user": "dok116", "ts": 1318280882000, "tid": 113652, "pn": 2}}', 1318280882000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1048223-me201', 'stk-user9096', 'ME 201', 'info', '{"desc": "من الصراحة أول كلاس حضرت فيه عندالدكتور ارتحت بالنسبة لشرحة وخاصة اللغة الإنجليزية كانت ممتازة و واضحة جدا\n\nلكن الخوف اللي كان عند الطلاب هو \" أنالأستاذ أول مرة يدرس الكورس يعني ماعندة خبرة عن نوعية الإختبارات وكيفية الأفكار فيها ومن القريدات \"\n\nلكن بصراااحة تامة الأستاذ كان مجتهد جدا جدا في توصيل الأفكار و متساعد في الكوزات في مواعيدها إذا كان فيه إعتراض من قبل الطلاب يأجل الكوز ز والكوزات كانت تجي من الهوموركات.\n\nبس الأستاذ لو يحل المسائل على السبورة يكون أفضل كثير\n\nانا دخلت الفاينل وقريدي قبل الفاينل +c لكن طلعت من الفاينل ماني متأكد من ولا إجابة وحدة وأقول يارب أجيب D , بس الأستاذ ماقصر تساهل معنا خصوصا الإختبار كان حريقة وأعطاني C .\n\nالله يجزاه خير ماقصر والله اللي مثله أخلاق وحبوب ومتعاون يستاهل كل خير 👍", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me201/126633/12", "user": "user9096", "ts": 1338406786000, "tid": 126633, "pn": 12}}', 1338406786000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1163241-me201', 'stk-metallic', 'ME 201', 'info', '{"desc": "ماشاء الله تبارك الله …\n\nهو انسان غريييييب ، ما يظلم أحد صحيح ، لكنه يوعد الطلاب بأنه اللي بيجيب درجة عالية بالفاينل أنه يعطيه أكثر من حقة وبأنه بيغض النظر عن المياجر … طبعاً هو كان يقول ما راح أساوي بين واحد مياجره والفاينل حلوه وبين اللي جاب درجة حلوه بالفاينل لحاله (الأول أفضل أكيد)، لكنه في وقت التشجيع هذا يجي في بال الواحد صورة والواقع بالأخير شيء ثاني …\n\nعموما الحمدلله على خلاصكم من هالكورس ، ومن نجاح إلى نجاح أكبر ان شاء الله … 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201-dynamics-final-grade/138271/6", "user": "METALLIC", "ts": 1358044189000, "tid": 138271, "pn": 6}}', 1358044189000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1047240-me201', 'stk-enough', 'ME 201', 'info', '{"desc": "اممممم أحسه مو عذر! كيف يعني كنت مذاكر على أساس إنها ريتين!\n\nالمادة تنفهم ! وبفهمك تحل … ما أعتقد راح تفرق اختيارات أو ريتن إلا في عدد الأسئلة والوقت اذا كان كفاية أو لآ!\n\nوعلى فكرة أنا أخذت المادة السميستر اللي راح وكان جزء تقريبا 30% من الاختبار اختيارات …\n\nأنا معاك ان الأسئلة المفروض ما تكون أغلبها اختيارات في مادة زي هذي!\n\nلكن جملة \" أنا مذاكر على أساس انها ريتين\" أحسها ما تنفع! ولا هي مبرر\n\nاحترامي … 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201/126548/39", "user": "enough", "ts": 1338253137000, "tid": 126548, "pn": 39}}', 1338253137000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p743774-me201', 'stk-user4392', 'ME 201', 'info', '{"desc": "اسمع وأنا اخوك\nنصيحة مجرب وشخص اخذ مع الاثنين\nيعقوب النصار ماااااااااااااا ينفع ولو كلاس واحد\nنزلت عند يعقوب النصار كورسين 201 و415\nكلها نفس القريد (الله يسامحه )\nلاشرح زين والقريدات عنده على حسب التصنيف حقه ان اعجبته اعطاك وان ما اعجبته ما اعطاك الا حقك\nوخلونا نكون صريحين اش يفيد الدكتور انه يكون اخلاق وما يعرف يشرح\nهذا رأيي في يعقوب النصار\nاما حسين القحطاني\nفشرح ممتاز وتصحيح ممتاز ودرجات حقك او ازود قليلا\n\nفي النهاية اقول لك لا تفرط في حسين القحطاني\nولك حرية الأختيار", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201-yaqob-alnassar-vs-husin-al-qahtani/99171/4", "user": "user4392", "ts": 1292305670000, "tid": 99171, "pn": 4}}', 1292305670000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p747709-me201', 'stk-raddadi', 'ME 201', 'info', '{"desc": "النصار كتعامل وبالاوفس اور ممتاز\nبالدرجات زي مادكر الاخوان ادا عجبته فابشر بال a+\nوالله اخدت معاه ثلاث كورسات الاول 201 وحليت سوال بالكويز الاول وكنت الوحيد اللي جاوب عليه بالسكشنين…للمعلوميه كان هو نبهنا عليه يعني مو فلاحه 100٪ بس اهتمام\nومن بعدها طبعتمعاه هدا ماياخد الا a+\nالكورس الاول كنت استحق ولكن الاثنين الاخيره والله قيمني على حسب نظرته فيني من خلال الكويز الاول بالماده الاولى واخدت a+\nلدالك بالنسبه للنصار وريه انك مهتم وتشوف نصيحه وريه انك مهتم وروحله باوقات غير قبل الاختبارات واسأل على اساس انك بتفهم (وتكون جاد بالفهم طبعا وبتدعيلي)\nبالنسبه للشرح فهو مقبول بس يعك اما التشوكبورد احيانا\n\nخريج قديم ومغبر كمان", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201-yaqob-alnassar-vs-husin-al-qahtani/99171/15", "user": "raddadi", "ts": 1292807790000, "tid": 99171, "pn": 15}}', 1292807790000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p850900-me201', 'stk-user4632', 'ME 201', 'info', '{"desc": "^^\nشكله كذا…\nانا مشكلتي جاء الدكتور حسين وسحب الورقه وقال الوقت خلص…\nالمشكله ماسمعت احد يقول باقي كذا 😦\nيعني كنت احسب باقي لي نص ساعه احل فيها السوال الاخير… وابراجع السوال الاول مادريت الا الوقت قاضي\nالصراحه غبنة والله… عاد السؤال الاخير اسهل سوال بالنسبة لي…\nضيق صدري ذا الاختبار الصراحه يعني السوال الاخير توني اقرا السوال…\nضاعت 25 درجه 😢\nوالنفسيه قفلت", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me201/108171/5", "user": "user4632", "ts": 1307842240000, "tid": 108171, "pn": 5}}', 1307842240000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p698872-me201', 'stk-user6749', 'ME 201', 'info', '{"desc": "انا درسني يعقوب النصار وكان نعم الدكتور\nفي التصحيح مايقصر وسمعته فتزويد القريد معروفه\nبالنسبة لأخلاقه انا اشوفه جدا طيب لكن الكثير غيري مايشوفون كذا\nخلاصة الامر اذا بينت للدكتور اهتمامك بالمادة والشرح ماراح يقصر معك ابد\nوبالاضافة انه يتميز بشي ماشفته عند اي دكتور مر علي الا وهي انه يهتم بفهم الطالب ومستعد يجلس معاك الاوفيس اور كله وحتى اذا خلص الوقت يستمر معاك لين تفهم حتى اني اذكر ان مر عليه دكتور يبغا شي منه وصفه وقاعد يشرحلي مع ان وقت الاوفيس اور خلص من زمان\n\nوبالنسبة للمياجر كومون", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201-course/94516/6", "user": "user6749", "ts": 1284054618000, "tid": 94516, "pn": 6}}', 1284054618000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1094250-me201', 'stk-user4626', 'ME 201', 'info', '{"desc": "الكورس أشوفه من الكورسات الحلوة نوعا ما و ماهو معقد مثل بع الكورسات إضافة إن الافكار واضحة و تدور حول مواضيع معينة\nفي سلايدات الدكتور جعفر البن موسى أشوفها مفيدة لفهم الأفكار العامة و بعدين حل الامثلة من الكتاب و أسئلة الهومورك و ممكن تزود أسئلة تختارها من الكتاب\nملاحظة : المادة ليست صعبة لكن الشاب يجدوها صعبة لانهم يقارنوها مع مواد مثل الثيرمو", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201/132060/4", "user": "user4626", "ts": 1347828535000, "tid": 132060, "pn": 4}}', 1347828535000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1154393-me201', 'stk-eng.mshari', 'ME 201', 'srcP', '{"html": "تفضل … 🌹<br><br>دعواتك …<br><br>​<span data-fid=\"stk-f1154393-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1154393-0": {"name": "ME201-Unsolved-FinalE-T112.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/c65d1fdbded2dce16c46d34d08fee3c87b1411d0dd8068e4c92ec081dc4cf179"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-201-old-exams/137447/5", "user": "Eng.Mshari", "ts": 1357282366000, "tid": 137447, "pn": 5}}', 1357282366000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_abdullah-me201', 'stk-abu_abdullah', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98197", "n": "Dr. Shahzada Shuja", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "-\n\nدكتور نفسية … جانا كلاس بدل دكتورنا برهان طشطوش لأنه ماقدر يحضر … وجلس يسفل فينا …\n\nشايف نفسة على ولا شئ !\n\nوالمشكلة رئيس القسم قطب معطية حرية وضع المياجر … والترم هذا مياجري كلها ورا بعض … تخيل Me 201 وبعدها Me 216 وقبلها بيوم Math 202 …\n\nوشباب أعرفهم مياجرهم السبت والأحد والأثنين … بإختصار وضع جميع مياجر مواد الميكانيكال في ثلاث أيام بسسس !!!\n\nنصيحة مثل اللي قبلي … إبعد عنة !!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1009370-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shahzada-shuja/98197/4", "user": "Abu_Abdullah", "ts": 1331897763000, "tid": 98197, "pn": 4}}]}', 1331897763000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2967-me201', 'stk-user2967', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98210", "n": "Dr. Yehia A. Khulief", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Me 201 - 101\n\nالتحضير : اخر اول 10 دقايق من الكلاس\nطريقة الشرح : ع البورد وتكتب النوت معاه … لان اختباراته تجي تقريبا زي امثلة النوت\nالكويزات : زي الامثلة بالكتاب بالضبط بس يعكس اتجاه او شي هيك\nالمياجر: مثل ماقلت قريبه من النوت بس لازم تبدع انت\nالفاينلات : نفس الكلام وعموما تعتبر متوسطه\nالقريد النهائي: A\nالصوت: واضح\nإضافات : يعطيك 5 اسئلة ع طول السمستر . اسئلة بونص كل فتره يعطيك سؤال\nلو تبي قريد بهالماده يمدحون واحد اسمه النصار ع مااظن\n\nوبالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p777166-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-yehia-a-khulief/98210/4", "user": "user2967", "ts": 1296214519000, "tid": 98210, "pn": 4}}]}', 1296214519000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8053-me201', 'stk-user8053', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98210", "n": "Dr. Yehia A. Khulief", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور ممتاز جيد في الشرح ومتمكن من المنهج وصاحب أخلاق عالية , ويعطي أسإلة بونص\n+\nالسلبيات : تصحيح شديد جدً و يخسف فيك\n\nترم 111 , me201", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1432515-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-yehia-a-khulief/98210/23", "user": "user8053", "ts": 1446943024000, "tid": 98210, "pn": 23}}]}', 1446943024000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-nasalmz-me201', 'stk-nasalmz', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98215", "n": "Dr. Muhammad Hawwa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "me 201 term 192\n\nما قبل كورونا يوم الكلاسات\n\nالتحضير: ما يحب اللي يدل متأخر يهزء شويتين بس يسمحلك تدخل ويحضر اخر الكلاس بالسيريال نمبر.\nالكوزات: اختبرنا واحد وكان ملتبل تشويز يعني انسى بارشال قريد وازيدكم من الشعر بيت والله مادري كم جبت لانه ما ارسل الدرجات اصلا، طبعا يوم اختبرنا الكويز الدكاتتره الثانين اختبروا ع الاقل 3 كوزات وحوا ما اختبرنا الا واحد. زيادة ان كان فيه ترك محد عرفله الا 3.\n\nالتصحيح: ف الميجر الاول كان تصحيحه عادي جدا.\n\nالشرح: عزيزي اللي قدر الله عليه وسجل عند حوا دبر عمرك اونلاين كورس الكتاب يوتيوب دبر عمرك!!!!!!\n\nاضافات:\n\nخله اخر خيار لك والله ع ما اقول شهيد.\nانسى تطلع الجوال ابدا\n\nايام الاونلاين:\n\nما كان يحضر ابدأ\nالشرح مازال يجيب الهم\n\nالمياجر كانت اونلاين والهوموركات اونلاين وكومن كلهن.\n\nنصيحه لوجه الله ترا الكورس سلاح ذو حدين حوا بيخليك تسحب ع الكورس ذاكر اول بأول اذا كنت عنده\nوالله يعينك اللي سجلت عنده.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522391-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-muhammad-hawwa/98215/6", "user": "Nasalmz", "ts": 1590429214000, "tid": 98215, "pn": 6}}]}', 1590429214000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kjl90-me201', 'stk-kjl90', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98215", "n": "Dr. Muhammad Hawwa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "192\nME 201\nالتحضير : ما يهتم كثير بالتحضير ويسمح بالميكاب اذا كلمته قبلها\nطريقة الشرح : اذا ناوي تاخذ المادة سلف ستدي نزلها عنده\nالكويزات : سهلة\nالمياجر: كومون\nتصحيحه للأمانة ممتاز ويدف\nالفاينلات :كومون\nالقريد النهائي: اذا انت حق سيلف ستدي وتبي تدكتور يدف ومتساهل بالحضور نزلها عنده وراح تنبسط 😆\nالصوت: واضح الى حد ما\nإضافات : الدكتور حليل و حايس شوي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525260-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-muhammad-hawwa/98215/7", "user": "kjl90", "ts": 1598861054000, "tid": 98215, "pn": 7}}]}', 1598861054000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11848-me201', 'stk-user11848', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98215", "n": "Dr. Muhammad Hawwa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم : ME201 - 192\n\nالتحضير : نهاية الكلاس غالبا\nطريقة الشرح : من سلايدات الكتاب\nالكويزات : متوسطة\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: A\nالصوت: واضح جدا\nإضافات : الدكتور مايحب التأخير , تصحيحه بطل ويدف وما يعتمد على الفاينل انسر , لو اخطيت في فقرة 1 وكملت الفقرات الباقية على اساس فقرة 1 الدكتور بيمشي معك وكأن حلك صحيح وبالاخير بيخصم شيء بسيط بس المهم قوانينك صح والخطوات اما الارقام ماتهمه مره\nيتقبل الاسئلة وما ينفس مهما كان سؤالك غبي , يشرح بالعربي كثير ويركز على الكونسبت مره\nالدكتور لو القاه بمواد ثانية بنزل عنده على طول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526004-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-muhammad-hawwa/98215/8", "user": "user11848", "ts": 1601632842000, "tid": 98215, "pn": 8}}]}', 1601632842000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-majed_als-me201', 'stk-majed_als', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98215", "n": "Dr. Muhammad Hawwa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 201 - 192\nما راح اتكلم عن التصحيح لأنه بترم كورونا، ولكن شرحه سيء ومستحيل تركز معاه. مستحيل تطلع الجوال ويتقعد لك. شخص طيب ويبغى يساعد لكن مثل ما ذكرت شرحه سيء.\nالمادة تعتمد على الفهم بالكلاس، ولذلك أنصح انك ما تنزل معاه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526537-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-muhammad-hawwa/98215/9", "user": "majed_als", "ts": 1604630842000, "tid": 98215, "pn": 9}}]}', 1604630842000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-amat_24-me201', 'stk-amat_24', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98216", "n": "Dr. Yagoub N. Al-Nassar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "me201 semester093\n\nشرحه عادي وكثير من الطلاب ما يعجبهم شرحه\nبس انا كنت افهم معاه\n\nالشرح كتابة (ورسم) على السبورة\n\nعلى ما اتذكر كوايزاته سؤال واحد طويل\n\nساعدني كثير في الكلاس وورك\n\nصوته واضح\n\nوتعامله طيب\n\nاحيانا كان يفتح كتاب يقرالنا منه اول 5 دقايق من اللكتشر عن الاخلاق اعتقد ماني متذكر الموضوع (مع رمضان يعني)\n\nالقريد النهائي: B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p839788-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-yagoub-n-al-nassar/98216/3", "user": "amat_24", "ts": 1304328389000, "tid": 98216, "pn": 3}}]}', 1304328389000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-s2010xxxxx-me201', 'stk-s2010xxxxx', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98216", "n": "Dr. Yagoub N. Al-Nassar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "me 201\nالتحضير :كل كلاس وعادي تتاخر 5-10 دقايق\nطريقة الشرح : سيء جدا ولا يحل اسئلة ابدا , ممكن يجيب سؤال محلول ويشرح نصه بس\nالكويزات : صعبه\nالمياجر:كومون وتصحيحه كان دف شوي\nالفاينلات :كومون\nالقريد النهائي:c\nالصوت: ممتاز\nإضافات : لا انصح في هذا المدرس ابدا , قالوا قبل ان شرحه سيء لكن بالقريدات كويس لكن للاسف معنا لا قريدات ولا شرح , ما فيه احد بالكلاس اخذ a+ , لا تاخذ عنده الا اذا كنت منحد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1228978-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-yagoub-n-al-nassar/98216/12", "user": "s2010xxxxx", "ts": 1369690341000, "tid": 98216, "pn": 12}}]}', 1369690341000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullatif1994-me201', 'stk-abdullatif1994', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98216", "n": "Dr. Yagoub N. Al-Nassar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المادة: Me201\nالترم: 141\nالتحضير : كان التحضير شبه يومي … وغالبا يحضر نهاية الكلاس … ومن اول غياب يخصم …\nطريقة الشرح : الشرح كان عن طريق سلايدات … طبعا بالغلط يحل امثله … يشرح وشرحه يجيب النوم شوي … يتطرق لمواضيع خارج الشرح ( طريقة توصيله للفكرة صعبه )\nالكويزات : كويزاته كانت من اصعب الكويزات الي مرت علي\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: C\nالصوت: شبه منخفض\nإضافات : اذا لقيت افضل منه نزل عنده … طبعا بلا مقارنه فيه افضل منه بكثير وفيه العكس …\n\n( منزل عنده me482 هالترم وان شاء الله اعطيكم تقييمي له بعد ماخلصها )", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1425774-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-yagoub-n-al-nassar/98216/16", "user": "Abdullatif1994", "ts": 1440562583000, "tid": 98216, "pn": 16}}]}', 1440562583000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-madridista-me201', 'stk-madridista', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98216", "n": "Dr. Yagoub N. Al-Nassar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "152 - ME201\n\nبإختصار شرحه سيء، يعني الداينمكس تتطلب حل تمارين حتى توصل الفكرة ومع ذلك ما اذكر استخدم السبوره\nيحب اللي يجيه في الاوفس اور،يعامل الكلاس معاملة العسكرية\nلا تنام لا تقعد عالجوال … حتى لو تسرح ثانيتين بيوقف شرحه عشان يناديك\n\nلكن بالقريدات بطل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1465115-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-yagoub-n-al-nassar/98216/19", "user": "Madridista", "ts": 1482516712000, "tid": 98216, "pn": 19}}]}', 1482516712000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5216-me201', 'stk-user5216', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98217", "n": "Dr. Mehmet Sunar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله\n\nالسمستر 102 … مادة me201\n\nالتحضير : اخر الكلاس ويسمح بالتاخير , لكن الغياب يحسبة عليك ويخصم بعد عدد معين من الغيابات والتحضير يكون بالصوت\n\nطريقة الشرح : ممتازه جدا يستخدم السبورة ونوته ممتاز ويوضح كل المفاهيم ويعطي امثله ويحل تمارين ويجاوب على الاسئلة بابتسامتة المشهورة واخلاقه العاليه … ونعم الاستاذ والله\n\nالكويزات : متوسطه الي سهله … ويسمح لك تفتح الكتاب … عطانا 5 كوزات واخذ افضل اربعه\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A\n\nالصوت: واااضح جدا ولهجته سليمه\n\nإضافات : المدرس جدا خلوق وطيب وحبيب وشرحه متعه لكن مشكلته انه متشدد في التصحيح وعلى كل خطاء يخصم حتى لو الاشارة غلط يخصم لو ان كل الحل صح … زينتة انه يعامل الطلاب كلهم بالمثل يعني زي مايخصم عليك يخصم على غيرك , يستاهل a+ بس عطيته a لانه في القريد النهائي قرر ياخذ الافرج العام ( ومااخذ افرج السكشن ) هالشي الي خلى كل الطلاب يجيبون العيد ( الي مأمل b اخذ c+ وهكذا ) وطبعا قرارة كان غير موفق لان باقي المدرسين يدفوون طلابهم وهو كان حقاني وكان المفترض يخليها افرج السكشن\n\nبالنسبة لي قررت في هالجامعه اشطف على شي اسمه اخلاق واركز على المدرسين المتساهلين والي يدفون في الدرجات وتصحيحهم معقوول ولو يرجع بي الزمن ورى مانزلت عنده ( لكني ماني نادم ابد الصراحه المدرس اخلاقه تشفع له الله يوفقه ويحفظة )", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p854315-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mehmet-sunar/98217/4", "user": "user5216", "ts": 1308304802000, "tid": 98217, "pn": 4}}]}', 1308304802000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-harry_potter-me201', 'stk-harry_potter', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98217", "n": "Dr. Mehmet Sunar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Me 201 - 102\n\nالتحضير : اول اسبوع ما حضر بعدين بدا يحضر كل كلاس آخر خمس دقايق تقريبا ولو انك جاي قبل ما يقول اسمك بدقيقه حضرك 🤠\n\nالشرح : شرحه حلو و مرتب يكتب نوت على السبوره مختصر ويحل اقزامبلين على كل موضوع تقريبا 👍\n\nالصوت : 10/10\n\nالكوزات : اختبرنا 5 كوزات اخذ افضل 4 كوزاته حلوه و يسمح بفتح النوت والكتاب 🤠\n\nالهوم ورك : كان يخلينا نسلم كل يوم اثنين الى الساعه 4 مع انه الكلاس كان الساعه 7 🙂\nواخذ افضل 10 هوموركات من 13 هوم ورك\n\nالمياجر والفاينل : كومن\n\nاضافات : الدكتور يشرح صدرك بابتسامته وهو افضل دكتور من ناحيه الاخلاق بالجامعه 🤴\nزي ما قالو الشباب التصحيح عنده سيء جدا وهذا هو عيبه بصراحه 😐\nيعطي هلب سشن رهيب قبل كل اختبار 🥊\nالافرج عنده نار كان 67 = C\n\nانا مع اني ما طلعت بقريد حلو من هالكورس الا اني نزفت معاه ME 309 لاني ارتحت معه 🥰", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p856067-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mehmet-sunar/98217/9", "user": "harry_potter", "ts": 1308571959000, "tid": 98217, "pn": 9}}]}', 1308571959000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8551-me201', 'stk-user8551', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98217", "n": "Dr. Mehmet Sunar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 201 - TERM 123\n\nالتحضير : بآخر الكلاس ، ينادي بالاسم و يحضر على ورقة ، أول ثلاث غيابات ما يخصم عليها ثم يبدأ يخصم 0.5 درجة لكل غياب ، لو تدخل قبل التحضير بخمس دقايق يحضرك عادي (ما يسجل المتأخرين) ، حريص عالتحضير و ما ينساه أبد.\n\nالشرح : يبدأ المحاضرة بشرح كونسبت الدرس الجديد أو يحل مسائل عالمحاضرة اللي قبل ، يحل بعض أمثلة الكتاب و بعض المسائل من الكتاب .\nطبعا يكتب عالسبورة بطريقة منظمة و خط جميل ، يرسم الدياغرام بطريقة واضحة لكن خطه صغير نوعا ما (اللي نظره تعبان يمكن ما يقدر يتابع معه).\nشخصيا ما أعجبتني طريقة شرحه أبدا و ما كنت أفهم معه ، الدكتور بااااارد بالشرح.\n\nالكويزات : أعطانا 4 كويزات و أخذ أفضل 3 (شوف المرفقات) ، كان يعطينا الكويز و يعلمنا بطريقة حله 😲.\nأفرج الكويز الأول: 7.4\nأفرج الكويز الثاني: 6.9\nأفرج الكويز الثالث: 7.6\nأفرج الكويز الرابع: 5.6\nيحط الحل عالويب سيتي و ما يتأخر بالتصحيح.\n\nالتصحيح : الدكتور ما يدور عن الخطأ اللي كتبته و يخصم عليك ، إلا يدور عالخطوات الصحيحة و يعطيك عليها درجات ثم يجمع درجاتك بآخر المسألة.\nالدكتور دقيق و عادل جدا في التصحيح ، على كل خطوة يحط قريد إذا كتبتها صح يعطيك عليها الدرجة.\nيعني مثلا A+B=C : يحط على الـ A درجة و على الـ B درجة و على الـ C درجة ، و بكذا يكون عادل بين كل الطلاب.\nيعني بإختصار يتابع خطواتك الصحيح.\n\nالمياجر و الفاينل : أخذت الكورس بالصيف فكان هو اللي يكتب الأسئلة ، أسئلته صعبـــــة بالحيل و غالبا يجيب أفكار جديدة ، خصوصا ميجر 2 و الفاينل سلخنا فيهم سلخ.\nأفرج الميجر الأول: 57.3\nأفرج الميجر الثاني: 55.9\nما أعطانا قريدات الفاينل.\n\nالقريدات : شوف المرفقات (الكويزات + الهومووركات + المياجر + الغيابات + الفاينل قريد) ، أغلب الطلاب يأخذون C عنده.\n\nإضافات :\n- أخذ أفضل 5 هومووركات من 6.\n- أخلاقه عالية جدا.\n- متساهل مع الطلاب في تحديد وقت الكويز / وقت تسليم الهوموورك.\n- الدكتور تركي الجنسية.\n\nمع إني أخذت معه قريد ممتاز و مع إن أخلاقه زي العسل ؛ لكن ما اظن إني راح أنزل معه أي كورس مرة ثانية.\n\n*الملف اللي بالمرفقات بدون درجة الفاينل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1253443-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mehmet-sunar/98217/18", "user": "user8551", "ts": 1376869686000, "tid": 98217, "pn": 18}}]}', 1376869686000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_faddagh-me201', 'stk-m_faddagh', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98217", "n": "Dr. Mehmet Sunar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده ME 201 ترم 153\n\nشرحه متوسط واعتقد لان المادة كانت صعبة شوي خاصة متيريال الفاينل\nللاسف كان ما يحل امثلة وتمارين غير امثلة الكتاب المحلولة فقط\nجيته مرة في المكتب قبل الميجر عشان يحل بعض الاسئلة ، بعضها ما يعرف يحلها فيرجع للسولوشن مانيوال!\nكويزاته سهلة جدا\n\nتصحيحه دماااااار\nتخيلوا كان فيه سؤال في الميجر رسمت فيه فري بدي ديقرام وحطيت كل القوى اللي تؤثر على الجسم ما عدا FN النورمال فورس لاني ما احتاجها في الكالكوليشن خصم عليي 3 بوينتس وقوة الاحتكاك حطيتها مع اتجاه الحركة وعوضتها بالسالب في الكاكوليشن خصم علي 1 بوينت !! احسه يدور اي زلة عشان يخصم الله يهديه\n\nترا اسئلته اللي يحطها في المياجر ناااار مقارنة بشرحه لذلك ابعد عنه اذا كان هو الوحيد اللي يدرس المادة\nميجر 1: 85\nميجر 2: 69\nميجر 3: 70\nفاينل : 12 من 20\nالقريد : B\n\nميزته اخلاقه وابتسامته وتفاعله مع الطلاب وتفهمه لظروفهم\n\nاعتقد انه خيار ممتاز لل309 ME\nاما ME201 ابعد عنه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467142-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mehmet-sunar/98217/26", "user": "m_faddagh", "ts": 1485596926000, "tid": 98217, "pn": 26}}]}', 1485596926000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_j_h-me201', 'stk-_j_h', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98219", "n": "Dr. Saif A. Al-Kaabi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 201 - T 132\n\nالتحضير :\n\nيحضر نهاية كل كلاس …\n\nطريقة الشرح :\n\nشرحو مو زين ولا شين تقدر تقول آفرج …\n\nالكويزات :\n\nكانت 4 ومستوياتها متباينة, دقيق جداً بالتصحيح فـ لا تسوي skip لأي step …\n\nالمياجر والفاينل :\n\nدايم كلاساتو أقل آفرج فالحياه, لكن ما عليك القريدات عندو by section …\nللأمانه يعطي قريدات مع ان الدرجات جداً طايحة …\n\nالقريد النهائي :\n\n+C …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1397753-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-saif-a-al-kaabi/98219/13", "user": "_j_h", "ts": 1409932348000, "tid": 98219, "pn": 13}}]}', 1409932348000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah-1-me201', 'stk-abdullah-1', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98220", "n": "Dr. Shafique Khan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Me201 ---- term 151\n\nالتحضير :\nاخررر الكلااااس وما يدقق فالتاخير اهم شيء تكون موجود اذا جاء يحضررر\n\nطريقة الشرح :\nيشرررح الكونسبت بشكل سريع بعدين على طووول يحل اكزامبلز\n\nالكويزات :\nالكووويزات سهلة جدا ومن الهومورك وحذف اقل واحد\n\nالمياجر:\nكومون وتصحيحه ممتاز\n\nالفاينلات :\nكومون\n\nالقريد النهائي:\n+a بالرااحة\n\nالصوت:\nيبيلك تجلس قدام لان صوته خفيف ولهجته بتتعود عليها مع الوقت\n\nإضافات:\nالدكتووور اخلاااااااااااااااااااااااااااق والكلاس معه خفييف جدا كانك منزل اسلامي\nبططططل وكررريم فالدرجااات … انصصصصح فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437895-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shafique-khan/98220/17", "user": "abdullah-1", "ts": 1451834199000, "tid": 98220, "pn": 17}}]}', 1451834199000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a_student1-me201', 'stk-a_student1', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98221", "n": "Dr. Hussain M. Al-Qahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا أخذت معه me 201 في 102\nشرحه : كنت أركز معه بداية الترم كان شرحه واضح ولغته واضحه و سهله\nيحضر يوميا بالبلاك بيري اللي معه لكن كم مرة قلت له اني حضرت و ماحضرتني ( أحس انه ما يهتم في التحضير )\nاخلاقه جدا طيبه و خلوق و متواضع و مبتسم مع من يحادثه\nاالتصحيح في المياجر والله ماش ماهوب ذاك الزود ولا الكويزات وأشك أنه هو اللي يصحح\nو الفاينل نفس الحتسي\nالله يوفقه لكل خير و يصير طيب الترم الجاي\nلأني نزلت معه 309", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p892817-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-hussain-m-al-qahtani/98221/10", "user": "A_student1", "ts": 1314529706000, "tid": 98221, "pn": 10}}]}', 1314529706000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahm2d1-me201', 'stk-ahm2d1', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98221", "n": "Dr. Hussain M. Al-Qahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 201 : TERM 191\n\nبدون ما اطول السالفه ، الدكتور سيء سيء سيء من ناحية الشرح وواضح انه مو فاهم الماده.\nالكويزات يجيبها من الهوموركات ويمديك تاخذ درجه عاليه في الكلاس ورك.\nتصحيحه في المياجر عادي بس ايام يدف حاجه بسيطه.\nبالنسبه لي ما اراح انزل معه اي كورس ثاني حتى لو كان اسلامي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518491-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-hussain-m-al-qahtani/98221/37", "user": "Ahm2d1", "ts": 1577750328000, "tid": 98221, "pn": 37}}]}', 1577750328000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bmm-me201', 'stk-bmm', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98221", "n": "Dr. Hussain M. Al-Qahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : Hussain Mohammad Al-Qahtani\n\nالمادة:ME201\n\nالفصل الدراسي:191\n\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير :يومياً نهاية كل كلاس. تقريبا يوم او يومين فقط الي ماحضر لضيق الوقت.\n\nطريقة الشرح :يحل الاقزامبلز الموجوده في سيلايدات الكورس .\n\nالكويزات :نسخ لصق من الهوموورك .سهل جداً تجيب فل\n\nمارك\n\nالمياجر: كومون\n\nالفاينلات :كومون\n\nالصوت: واطي شوي اذا كنت اخر الكلاس صعب تسمع .\n\nإضافات :- هذا الدكتور عنده ميزه الا وهي التصحيح . تصحيحه أسطوووووووري جداً. حرفياً يعطيك درجة على اي شيء تكتبه ومهما كنت متوقع درجتك راحتلقاها أعلى\n\n- عنده ميزه ثانيه بس للاسف انا ما استفدت منها، الا وهي انه مهما كانت درجاتك ضعيفه في المياجر بس انك شديت حيلك في الفاينل وجبت 30/35\n\nA ممكن تطلع ب\n\nعلى قولة الدكتور :\n\n( I heavily depend on the final)\n\nالقريد النهائي:\n\nA+ وبجدارة\n\nصراحة أعطاني قريد اكثر مما استحق بالاضافة الى أخلاق الدكتور العالية ( أول مره اشوف دكتور يطلب من الطالب انه يشيل الجوال ويركز معاه وبعدمايشيل الجوال يقول له شكراً)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518606-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-hussain-m-al-qahtani/98221/38", "user": "BMM", "ts": 1577894482000, "tid": 98221, "pn": 38}}]}', 1577894482000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-al-houri-me201', 'stk-al-houri', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98223", "n": "Dr. Abdelaziz Bazoune", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الترم : 161\nالمادة : ME 201\n\nالتحضير : كل يوم في نهاية كل محاضرة (ينادي على الأسماء) وأول إسبوع في الدراسة ما يحسبه\n\nطريقة الشرح : يكتب أهداف المحاضرة (Objectives) والقوانين المهمة - يستخدم السلايدات للعرض ويحل مسائل في السبورة من السلايدات - يبين كيف جت القوانين - يستخدم الفيديوهات الموجودة في السلايدات للشرح - يمثل بعض الأشياء بأقلامه - سلايداته ممتازة - يحل من مثالين إلى ثلاثة أمثلة\n\nالكويزات : تقريباً في كل اسبوع يوم الخميس (عطانا 8 كويزات تقريباً - ما حسب الا 4 منهم) - كل كويز عشرين دقيقة ويحتوي على سؤال واحد - سهل إلى متوسط\n\nالمياجر: تصحيح عادل ويعطيك شوي زيادة عليه - يتأخر في التصحيح عشان يتأكد من تصحيحه - كومن\n\nالفاينلات : كومن\n\nالصوت : واضح ومفهوم - لغته ممتازة - صوته عالي\n\nإضافات :\n١)- الدكتور ما يحب أحد ينشغل في المحاضرة فيطرد اللي يشوفه يستخدم جواله أكثر من مرة ويخلي النعسان يغسل وجهه\n٢)- منظم ومرتب\nأ- كل شيء ينزله في البلاك بورد (بعض الأحيان يتأخر في التنزيل) مثل: أماكن المياجر - سلايداته - وقت تسليم واسئلة الواجبات المطلوبة وحلولها وCover Page - حلول الكويزات - والسيلابس - ونسخة study pack للكتاب\nب- مرتب في الكتابة في السبورة\n٣)- يعطي مجال لمشاركة الطلاب\n٤)- ما يصحح الواجبات (grader هو اللي يصححهم)\n٥)- يأخذ برأي الطلاب في بعض الأمور بعد نقاش مثل (تسليم الهوموركات وموعد يوم off)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466956-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdelaziz-bazoune/98223/11", "user": "Al-Houri", "ts": 1485302829000, "tid": 98223, "pn": 11}}]}', 1485302829000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-daho0omy.10-me201', 'stk-daho0omy.10', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98223", "n": "Dr. Abdelaziz Bazoune", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الترم : 172\nالمادة : ME 201\n\nالتحضير : كل يوم في نهاية كل محاضرة (ينادي على الأسماء)\n\nطريقة الشرح : يكتب أهداف المحاضرة (Objectives) والقوانين المهمة - يستخدم السلايدات للعرض ويحل مسائل في السبورة من السلايدات، شرحه متوسط بس سلايداته ممتازة.\n\nالكويزات : عطانا ٣ كويزات وكانت صعبة الى متوسطة\n\nالمياجر: كومن - تصحيح شديد مرة\n\nالفاينلات : كومن\n\nإضافات :\n-الدكتور ما يحب أحد ينشغل في المحاضرة فيطرد اللي يشوفه يستخدم جواله أكثر من مرة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1502035-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdelaziz-bazoune/98223/12", "user": "daho0omy.10", "ts": 1541536951000, "tid": 98223, "pn": 12}}]}', 1541536951000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-me201', 'stk-guest', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f182902", "n": "Dr. Nizar Jaber", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "me201\nterm201 اونلاين\n\nالتحضير : عن طريق البلاكبورد\n\nطريقة الشرح : سلايدات القسم ، يشرح الكونسبت بعدها يحل سؤالين او ثلاثة\n\nالكويزات : كل اسبوع في كوز ، الكوزات تنقسم قسمين\n١- اسالة كونسبت- اسبوعياً\n٢- مسائل كل- ثلاث اسابيع\n\nالمياجر: كومن ، اختياري و مسائل تصور و ترفعها pdf\n\nالفاينلات :كومن ، اختياري و مسائل تصور و ترفعها pdf\n\nلقريد النهائي:A+\n\nالصوت: واضح\n\nإضافات : الدكتور نزار قمة في الاخلاق و فنان جداً في الشرح و يبسط المعلومه و ما ياخذ الكلاس كامل يعني قبل ب ١٠ او ٥ دقايق يكون مخلص ، يجاوب على الاساله ، مع وضع الاون لاين كثير دكاتره ساحبين على الساعات المكتبيه اما دكتور نزار كان شبه يوميا عنده على تيمز تدق عليه و يرد عليك ، يتاخر في التصحيح بس انا اشوف انه معذور بسبب انه عنده حول ثلاث او اربع سكاشن ، الدكتور كان هو الحسنه الوحيده في هذا السمستر التعبان احرجنا بتعاونه و اخلاقه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527649-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nizar-jaber/182902/4", "user": "Guest", "ts": 1609928673000, "tid": 182902, "pn": 4}}, {"id": "stk-dr-f98223", "n": "Dr. Abdelaziz Bazoune", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الترم 203 ( اونلاين واختبارات حضوري)\nالمادة ME201\n\nالتحضير :\nكان يحضر اخر الكلاس بعد ما يخلص وما حاسب عالتاخير ولا مرة\n\nالشرح :\nالدكتور شرحه متوسط واحيان اقل وتحسه احيان يقرا السلايدات\nوماكان يرضى انه يسجل الكلاس\nبس انت عندك الاونلاين كورس وفيه واحد باليوتيوب مصري شرحه ممتاز واصلا ميزة المادة مصادر مذاكرتها كثير فالبنسبة لي مافرق شرح الدكتور معي\n\nالكويزات:\nالاسئلة كانت اما خيارات او انك تكتب الجواب وماعنده بارشل بالكويزات وصعوبتها كانت تتفاوت من متوسط لصعب\nاختبرنا 7 كويزات وحذف اسوء 2\n\nالتصحيح:\nطبعا الداينمكس بالمد والفاينل جزء كبير منه رتن ، بخصوص الفاينال ماعلمنا الدرجات حقت كل واحد وبالمد علمنا والافرج كان طايح بس بالنسبة لي توقعت اجيب درجة سيئة جدأ ولقيت اني فوق الافرج\nمحد يمدح تصحيحه يمكن انا الوحيد الي اشوفه اعطاني فوق حقي\n\nالتعامل:\nتعامله مع الطلاب كويس ومن ال7 كويزات الي اختبرناها يمكن حول 4 كويزات كنا نطلبه ياجل الكويزقبل لا يبدأ ( باجماع الطلاب ) ويقول عادي ما ابغا اصعب عليكم انا هنا لتسهيل المهمة مو لتصعيبها\n\nاضافات:\nالدكتور كان يزيد بعض الطلاب درجتين على مجموعهم النهائي للي يجاوب على سؤال هو سأله وقت الشرح\n\nفيه شي ابدأ ماعجبني بالدكتور ، بعد المد كان فيه اجازة بنص الترم حول اسبوعين ، مارضى ينزل الدرجات حقت المد الا لما يبدا الدوام بحجة انها اجازة !\nالمشكلة ان فيه ناس تبغا تدردب ومنهم انا ماكنت اعرف ادردب ولا اذاكر بالاجازة وكلمته ايميل ولا رد\n\nوالفاينال ماعلمنا لا درجاتنا ولا الافرج ولا حتى توزيع القريدات بس نزل القريد بالبورتال", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531317-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdelaziz-bazoune/98223/14", "user": "Guest", "ts": 1629269548000, "tid": 98223, "pn": 14}}]}', 1609928673000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-me4me44-me201', 'stk-me4me44', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f98224", "n": "Dr. Mahir Hassan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "دكتور قمة في الأخلاق والتسامح 🥰\nوفي التصحيح تأخذ حقك وبزيادة\nكويزاته سهله\nتحضير : ورقة وتوقع\n\nولكن للاسف في الشرح غير لائق إطلاقا\nأ خذت معاه me201,وصار الكورس كله على راسي 😭\nطبعا المياجر والفاينلات كومن\nأنصح فيه للمواد غير الكومن", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p751798-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mahir-hassan/98224/3", "user": "me4me44", "ts": 1293304527000, "tid": 98224, "pn": 3}}]}', 1293304527000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-heisenberg-me201', 'stk-heisenberg', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f118630", "n": "Dr. Hassen M. Ouakad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "152 ME201\nلتحضير :اخر الكلاس.اذا حضرت لك 5 درجات بونص واذا ماحضرت عادي.حتى لو تدخل اخر شي يحضرك.\nطريقة الشرح :من سلايدات .يشرح كويس بس مشكلته يتكلم بسرعة .اذا سألته يستانس.\nالكويزات :فيه السهل وفيه الصلخ.الصلخ كان اخر اسبوع دوام ثلاث كوزات .\nالمياجر:كومن\nالفاينلات :-\nالقريد النهائي:a+\nالصوت:واضح\nإضافات :تصحيح الدكتور عسل مو دف ترفس 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1449259-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-hassen-m-ouakad/118630/28", "user": "HEISENBERG", "ts": 1463436018000, "tid": 118630, "pn": 28}}]}', 1463436018000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5712-me201', 'stk-user5712', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f118631", "n": "Dr. Jafar Al-Bin-Mousa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "طبعاً الشباب اللي فوقي كلهم قيموا الدكتور قبل ما ينتهي السمستر ، وهذا أول تقييم بعد ما عطانا الدرجات\n\nME 201-112\n\nالتحضير :\nيمرر ورقة ، وفي نهاية السمستر اكتشف ناس كان يحضروا بعض وطلب منهم يراجعوه في المكتب.\nبشكل عام متساهل في التحضير ، لكنه ما يعطي الطلاب غيابين مجاناً مثل بعض المدرسين.\n\nطريقة الشرح :\nيشرح من سلايدات ويستخدم السبورة بعض الأحيان لتوضيح بعض الأفكار. شرحه يعتبر ممتاز ويعطي أمثلة كثيرة جداً ، لكن كل أمثلته بسيطة وأساسية وتعتبر تطبيق مباشر للقانون.\nوهذي هي مشكلته في الشرح وهي أنه ما يهيأ الطالب للمياجر ، يتعب في الشرح ويعيد ويزيد في الأفكار الرئيسية (المأخوذة من الكتاب) ويتجاوب مع أسئلة الطلاب بصدر رحب ، لكنه ما يتطرق للأفكار اللي تجي في المياجر ، وهذا أعتقد بسبب أنه جديد في القسم ولا يعرف طبيعة الأسئلة.\n\nيعني أنا عجبني شرحه وفهمت عليه ، لكنه وهقني في المياجر وصرت في المياجر أستنبط قوانين من القوانين الأساسية اللي هو عطانا في اللكتشر وضاع الوقت علي ، بينما طلاب الدكاترة الثانين وخصوصاً “يحيى خليف” كان يوضح لهم ويش اللي يذاكروه ويعطيهم أمثلة قريبة من المياجر.\n\nالكويزات :\nعطانا 5 كويزات وأخذ أفضل 3 .\nأول 3 كويزات كان يحدد لنا هومورك من الهوموركات ويطلب منا نركز على جميع أسئلته ، وبعدين يجيب لنا سؤال قريب من أحد أسئلة الهوموركات مع تغيير فكرة بسيطة.\nوفي آخر كويزين طلع لنا بحركة بايخة وهو أنه يحدد هومورك من الهوموركات ويطلب من الطلاب أنهم يعطوه سؤال شبيه بأحد أسئلة هذا الهومورك وهو يختار أفضل واحد فيهم ويعطي الطالب اللي كتب هذا السؤال درجة كاملة .\nأنا أشوف هالحركة مالها داعي لأن الطلاب بعضهم يعقدوا السؤال أو يحطوا فكرة جديدة ، علشان يثبتوا للمدرس أن سؤالهم يستحق أنه ينعطى للطلاب في الكويز والطالب نفسه يآخذ درجة كاملة ، أنا عن نفسي ما سلمت له ولا سؤال.\n\nالمياجر:\n(1) طبيعة الأسئلة :\nالميجر الأول كان نوعاً ما معتدل وأسئلته متوسطة وعددها 3 أسئلة ، لكن الميجر الثاني كان انتكاسة عظيمة لي ، بحيث أني أول مرة في حياتي أطلع من ميجر بدون ما أحط ولا جواب نهائي في ورقة الأسئلة ، لدرجة أن “الدكتور جعفر البن موسى” لما حل الإختبار الثاني كان يخطأ في الخطوات وورقة الإجابة في يده. وطبعاً كالعادة “جعفر البن موسى” ما حذرنا قبل الإختبار بأنه رايح يكون صعب ولا رضى حتى إنه يعلمنا كم عدد الأسئلة ، بينما “يحيى خليف” حط سؤال في الميجر كان كاتبنه لطلابه في المذكرة حقته مع تغيير بسيط للسؤال.\n\n(2) تصحيحه للمياجر:\n* طريقة تصحيحه بشكل عام هو أنه يسوي له key solution بخطوات معينة ويحط لكل خطوة درجة معينة ، وأنا برأيي أن هذي الطريقة هي ألعن طريقة في التصحيح ، والدليل أنه ولا طالب قدر يآخذ فل مارك في سكاشنه الأثنين في كل المياجر.\n* بالنسبة للميجر الأول ، زي ماقلت كانت طريقته دماار ونزلنا قريدات على أشياء بايخة ، لكن طريقة تصحيحه هذي أفادت الناس اللي جايبين العيد في الميجر ، لأنه حسب لهم درجات حلوة على قانون بسيط ، أما الممتازين فما عجبهم لأنه يدقق على كل خطوة ، ويحط درجة ماهيب شوية عل الجواب النهائي. وينقص حتى على الدايركشن وحتى free body diagram وعلى أشياء كثيرة مالأمها داعي في فهم الطالب.\n* أما الميجر الثاني (آآآآآه ياقلبي على الميجر الثاني) فكان تصحيحه أقل تشدد ، لأن الطلاب عصبوا عليه وتكلموا معه وقالوا له أنهم جايبين العيد ، لكن بشكل عام ما تغير تصحيحه بشكل كبير ، وأعلى درجة كانت 81 لأحد السكاشن و 87 للسكشن الثاني ، ومع هذا يقول أنه تحسف لأنه زيد الطلاب وقال لنا “أنا ما بتهاون في تصحيح الفاينال مثل الميجر الثاني” وبالفعل هذا اللي صار.\n\nالفاينلات :\nوقت الفاينال كان في الأسبوع الثاني يوم الأثنين بالليل ، يعني عندهم يوم واحد فقط لتسليم الدرجات ، علشان كذا جابوا لنا خيارات 80% وسؤال ريتن 10% وخبصوا أم الدعوة وخيبوا كل آمالنا في أن نجيب قريد حلو.\nوكالعادة “البن موسى” ماعطانا خبر أن الإختبار اختيارات ولا تكلم عن مدى صعوبته.\nتصحيحه للفاينال ما شفناه لكن عطانا درجتنا في الفاينال وكانت مخيسة بمعنى الكلمة.\n\nالقريد النهائي:\nما أدري ويش أعطيه ، أحس أنه يقدر يكون أفضل مدرسين هذا القسم (يعني +A) لكن لو يعدل طريقة تصحيحه شوي ولا يصير يدقق واجد في الخطوات.ويقدر يصير مدرس مش حالك لو بقى بطريقة تصحيحه الشديدة (يعني B).\n\nإضافات :\nأنا متأمل خير من هالدكتور وأخلاقه حلوة وتفاعله مع الطلاب جيد ، ولامرة شفته يتكبر على أي طالب أول يحاول ينفر الطلاب منه وكان يأجل لنا الكويزات إذا طلبنا منه ويأجل لنا الهوموركات إذا كنا مضغوطين ، لكن والله أنه مخرب على نفسه بطريقة تصحيحه اللي مالها داعي ، وأكبر دليل على كلامي هو أنه ما أحد قدر يجيب فل مارك في كل اختباراته ، المفروض أن مدرس درة مثل “جعفر البن موسى” يصير طيب في التصحيح مثل “وائل أحمد” و “السرخي” وغيرهم ، هذولي الدكاترة طريقة تصحيحهم هي أن أول شيء يشوفوه هو الجواب النهائي إذا كان صحيح يعطوك فل مارك على طول ، وإذا كان خطأ يتابعوا خطوات حلك (بعيونهم فقط وليس بقلمهم الأحمر) ويشوفوا إذا كنت فاهم الفكرة يخصموا درجة أو درجتين فقط من السؤال كاملاً من أصل 30 درجة (والله العظيم هذه هي طريقة تصحيحهم). طبعاً أنا ما أنكر أنه ساعدنا في نهاية السمستر في letter grade ، لكن لو كان يصحح لنا مثل الناس كان جبنا درجة أحسن من اللي عطانا.\n\nلكن المدرس جديد وأنا أتوقع أنه بيكون من أفضل المدرسين في السمسترات القادمة (إن شاء الله) ، إذا انتبه لعيوبه وحاول يعدلها\n\nأنا أدري إني طولت عليكم في تقييمي ، لكني حبيت أزيل اللبس حول هذا الدكتور الفاضل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1048267-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jafar-al-bin-mousa/118631/6", "user": "user5712", "ts": 1338412778000, "tid": 118631, "pn": 6}}]}', 1338412778000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-stu2009-me201', 'stk-stu2009', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f118631", "n": "Dr. Jafar Al-Bin-Mousa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "[quote=“تقييم”]\n\n**\nbinmousa@kfupm.edu.sa\n\nبنود التقييم :\nسمستر113-كورس Me201\n\nالتحضير :\nيوميا وأتذكر مرتين فقط ما حضر طول الصيف:)\nطريقة الشرح :\nيشرح من سلايداته الخاصه ويتفلسف شوي في الشرح…وأحيانا يضيع اللي يتبعوا معاه في الشرح\nالكويزات :\nالكويزات كانت شوي أصعب من الأمثله اللي يشرحها على في الكلاس وفيها أفكار خارجيه أحيانا\nالمياجر:\nكان هو الكوردنيتر لأنه الدكتور الوحيد اللي منزل الماده…المياجر كانت سهله جدا والأفرج نار 🤪\nالفاينلات :\nنفس حركة المياجر ولكن صعب شوي لأنه شاف ان الأفرج كان مرتفع جدا فصعب علينا شوي في الفاينل عشان ينزل الأفرج 🤠\nالقريد النهائي:\nأعطيه A الى B+\nالصوت:\nواضح والأكسنت حلو\nإضافات :\nالدكتور ممتاز للي يعتمد على نفسه أما للي يعتمد على شرح المدرس فينصح بالبحث عن مدرس اخر 🌹\nوطبعا نقطه مهمه انه متساعد جدا في القريدات 🌹**", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1076265-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jafar-al-bin-mousa/118631/10", "user": "stu2009", "ts": 1344214226000, "tid": 118631, "pn": 10}}]}', 1344214226000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-montadhar-me201', 'stk-montadhar', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f118631", "n": "Dr. Jafar Al-Bin-Mousa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المادة: ME201\nالسمستر: Summer session 113\n\nطبعا لما جيت أسجل للصيف و السمستر كنت متخوف أنزل عنده ME307 لأني كنت خايف يطلع مش و لابد في الصيف و لكني تأسفت أني ما نزلت عنده ME307.\n\nالتحضير: بالأسماء يوميا و في كم يوم ما يزيدوا عن 4 ما أخذ الحضور.\n\nالشرح: في الكونسبت ممتاز جدا جدا بس عيبه حتى المسائل محلوله و يشرحها بالكلام.\n\nالأخلاق : طيب ﻷبعد الحدود و دمه خفيف و عليه قطات بعض الأحيان تخليك تموت من الضحك بالإضافة إلى أن متعاون جدا في الأوفس حتى في غير المادة ، عن جد تعبته معاي من الأسئلة سواء في المادة أو خارجها و كان يتلقاها برحابة صدر.\n\nالكويزات: نص و نص و أكثرها من الكتاب و كان عددها ثلاثة و الرابع ميك أب أونلاين.\n\nالتصحيح: هم بعد نص و نص بمعنى أنه يشد في أماكن و يرخي في أماكن ثانية بس بشكل عام زين.\n\nالقريد النهائي: A و أتوقعه راح يكون A++ في المشين ديزاين لأنها تخصصه.\n\nملاحظات: الدكتور اتبع الأسلوب اللي من المفترض الجامعة تتبعه و هو إعطاء الطلاب اختبارات تركز على الفهم مو للتحدي و لكنه للأسف في النهاية اتبع أسلوب الجامعة في القريدات، هو بصراحة ساعد الطلاب اللي يستحقوا بس مع ذلك أنا كنت متوقع آخذ قريد أعلى مقارنة بالسمسترات اللي طافت.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1082804-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jafar-al-bin-mousa/118631/11", "user": "montadhar", "ts": 1346247384000, "tid": 118631, "pn": 11}}]}', 1346247384000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-trad-me201', 'stk-trad', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f118631", "n": "Dr. Jafar Al-Bin-Mousa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME201-Term 192\nنص حضوري ونص عن بعد\n\nالتحضير :\nبالنسبة للحضوري كان يحضر بالاسماء نهاية الكلاس ويطلع لك التحضير بالبلاكبورد بعدها يوم صارعن بعد اول ما تخش زووم وتكتب اسمك والايدي حقك في الشات\n\nطريقة الشرح :\nيشرح من سلايدات وكان شرحة جدا ممتاز وجدا متمكن ماشاء الله واسلوبه جميل في الشرح\n\nالكويزات :\nطبعا ماعطانا الا كويزين بس وقت الحضوري وكانت صعبة نوعاَ ما وهو اصلا قال لنا بداية السمستر انا كويزاتي صعبة عشان اجهزكم للمياجر\n\nالمياجر: كومون وطبعا ماخذنا الا ميجر واحد فقط وهو اللي صححه وكان تصحيحه ممتاز جدا وتاخذ حقك وزود\nالفاينلات :كومون\n\nالقريد النهائي: A\n\nالصوت:ممتاز\n\nإضافات :الدكتور محترم جدا واسلوبه حلو, الرجال جدا متمكن في المادة ويحببك فيها ,طبعا انا سحبت عالمادة من بعد الميجر الاول فبالنسبة للقريدات انا خذتها NP/NF ومدري صراحة عن اللي خذوا IC وهل الدكتور ساعدهم ولا لا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527629-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jafar-al-bin-mousa/118631/31", "user": "Trad", "ts": 1609866494000, "tid": 118631, "pn": 31}}]}', 1609866494000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-illusions-me201', 'stk-illusions', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f118644", "n": "Dr. Sulaman Pashah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Me201\nTerm 173\n\nالتحضير : يحضر اول دقيقة ويحضر عقب الكلاس ولا يحط ليت لاحد. واتوقع يحذف عليك ثلاث غيابات ما يخصمهم بنهاية الترم منب متأكد\n\nطريقة الشرح : سلايداته , بدايتها شرح كونسبت وبعدين يعطيك امثلة الكتاب , بس مفصلها لك وحاطها بألوان , ومفصلها اقصد انه تفتح المثال بالكتاب وتفتح السلايد تلقى حل اطول و بخطوات اكثروملونة كل خطوة , مب مباشر ويفترض انك فاهم زي الكتاب فكانت تفيدني كثيييير بالفهم\n\nالكويزات : عطانا 6 كويزات واخذ اعلى 4 , كويزاته ما كانت صعبه ولا كانت سهله الصدق واخبر افرجهم كان بالغالب حول سبعه , اذا ذاكرت لهم بتحل كويس. وكان جدا متعاون بوقتهم لدرجة انه يجمع الكويزات الي على نفس جزئية الميجر بيوم الميجر يقول لاني داري انه صيف وانكم مضغوين فهذا انسب وقت لكم. وكان يعطينا سؤالين بوقت الكلاس كامل وانا الصدق اقدر الدكتور الي كذا , يعطيك راحتك وانت تحل , ويحسسك ان الكويز صدق له قيمة من درجاتك.\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي:A+ . من افضل الي درسوني بالجامعة\n\nالصوت: واضح وانقليزيته حلوه وتنفهم.\n\nإضافات : الدكتور اخلاااق واذا سألته حتى لو سؤال غبي يعيده المعلومة من جديد بكل رحابة صدر, حتى اذا حس الطلاب ما فهموا شغله وسلكوا له يضحك ويقول واضح انكم ما فهمتوها بس ارجعوا لها وبتلقونها سهله واذا فيه مشكلة تعالوا لي بأي وقت عادي احلها. كنت ادخل عليه بعض الاحيان بكوفي ومتأخر خمس دقايق ولا كان يقول لي اي شي من كثر ما هو طيب لبى قلبه.\n\nتصحيحه يعطيك اعلى من حقك بشوي بس اذا شافك فاهم حتى لو ارقامك غلط يضبطك بالدرجة , واذا رحت كلمته مب من النوع الي ما فيه امل انا غلطان بالعكس مع شوي كلام ممكن يزيدك درجتين فمتفهم مره ,هذا طبعا اذا جيته بشي منطقي. فبشكل عام اذا حسك فاهم لا تخاف على درجتك عنده.\n\nبداية الترم كان يقول لنا ان المادة افرجها اوفر اول لكل السكاشن , ومع الوقت الدكتور الثاني الطلاب يقولون يعطي طلابه تلميحات عن الاسئلة فالافرج حقهم اعلى مننا , فكلمناه وقلنا له افصلنا عنهم لان افرجهم عالي ولمحنا له , فقال بشوف اذا انتم مره متأثرين بسبتهم بفصل الافرج وبسوي لكم احسن شي اقدر عليه , مدري وش سوا الصدق بس قريدي كان اعلى من الي اتوقعه لان الافرج كان عالي نسبيا فجزاه الله خير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1497856-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-sulaman-pashah/118644/19", "user": "ILLUSIONS", "ts": 1534415293000, "tid": 118644, "pn": 19}}]}', 1534415293000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-paatchi2013-me201', 'stk-paatchi2013', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f118645", "n": "Dr. Salem Bashmal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Me201 151\nالتحضير : يحضر بداية الكلاس وشديد بالتحضير\nطريقة الشرح : شرحة من عادي الى متوسط بس انه يسوي كل اللي يقدر عليه عشان يوصل المعلومه\nالكويزات : شبيهه للهومورك\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: ادرس معه حاليا\nالصوت: واضح\nإضافات : الدكتور تصحيحه ممتاز ويعطي مسائل تقريبا في كل كلاس وعليها بونص\nومايخصم على الغياب بس يعطي بونص للحضور", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1434228-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/salem-bashmal/118645/7", "user": "paatchi2013", "ts": 1448225848000, "tid": 118645, "pn": 7}}]}', 1448225848000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_aviator-me201', 'stk-the_aviator', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f118645", "n": "Dr. Salem Bashmal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم\nME 201 DYNAMICS ------- Term 151\nالتحضير : بداية الكلاس اول دقيقة ، يحضر المتاخر نهاية الكلاس بس لا تاخذها حلااا 🙂\nطريقة الشرح : اشوفها كويسة، يعني تذاكر اول باول وتقعد في الصف الاول وتتابع معاه امورك تمشي في المادة . من ايجابيات الشرح يعلمك كيف تفرق بين المسائل ومتى تستخدم القوانين . من سلبيات الشرح اذا حل مسالة على السبورة ما يحلها حل كامل ، يحل الاجزاء الاساسية ويخليك تفهم الباقي ، بس في الاخير شرحه كويس يعني تفهم اذا انتبهت معه .\nالكويزات : سهلة من اسئلة الهوموورك وامثلة الكتاب المحلولة .\nالمياجر والفاينلات : common\nالصوت : واضح\nالقريد النهائي : A\nاضافات :\n1 - يدففففففف في التصحيح ، يعني حتى لو حلك غلط يطالع في الحل ويطلع لك كم درجة ويزيدك .\n2 - ما يحب الجوالات ، فلا تحط نفسك بموقف محرج لأن الرجال محترم واخلاقه عالية.\n3 - شغله مرتب ، يعطي outline فيه مواعيد تسليم الواجبات وكل الكوزات ، يرصد كل الدرجات بالبلاكبورد يعني قبل ما يطلع القريد النهائي بالبورتال راح تكون عارف بالضبط كم مجموعك من 100 .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438025-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/salem-bashmal/118645/8", "user": "THE_AVIATOR", "ts": 1451921960000, "tid": 118645, "pn": 8}}]}', 1451921960000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammedj-me201', 'stk-mohammedj', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f118645", "n": "Dr. Salem Bashmal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME201-171\n\nالتحضير : نهاية الكلاس\nطريقة الشرح : يشرح على سلايدات ويحل مسائل بعض الأحيان, اشوف شرحه عادي.\nالكويزات : كل كويزاته اون لاين, تحلها في بيتكم ومسموح تستخدم الكتاب النوتات او اي حاجه, وحتى كان يقولنا الكويز بيكون مشابهه للمسائلة الفلانية في الصفحة الفلاينة.\nالمياجر:----\nالفاينلات :------\nالقريد النهائي:A+\nالصوت: واضح\nإضافات :\n- تصحيحه جبار والافرج عنده B.\n- دكتور اخلاق ودايم مبتسم ومتعاون مع الطلاب.\n- كان مسهل علينا المادة ومريحنا لدرجة انك ما تحس انك منزل داينمكس, الله يجزاه خير.\nرابط عن الكورس:\nME201 - Google Drive", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492622-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/salem-bashmal/118645/9", "user": "mohammedj", "ts": 1526577399000, "tid": 118645, "pn": 9}}]}', 1526577399000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_shaer6-me201', 'stk-m_shaer6', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f118645", "n": "Dr. Salem Bashmal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME201 - ترم 172 …\n\nالتحضير :\nتحضير يومي بداية الكلاس، يحاسب ع التأخير والغياب …\nتقدر تشوف حضورك وغيابك في البلاك بوورد …\n\nطريقة الشرح :\nفالبداية يشرح الكونسبت ع السبورة ويتكلم عنه، بعدين يحل كم مثال من السلايدات …\nشرحه يعتبر نوعاً ما ممل شوي، لكن الأمثلة الي يحلها فيها افكار حلوه ومفيده ومهمه …\nيعني اذا انك من النوع الي يراجع اول بأول، راح تستفيد من امثلته كثيييييييير …\nفالكلاس راح يحدد لكم الأشياء الي يحتاج تكتبها فالميجر، وينبهكم من الاخطاء الشائعه …\n\nالكويزات :\nاذا مانا غلطان اعطانا 4 او 5 كوزات اونلاين ع البلاك بورد، يكونوا خارج وقت الكلاس …\nو اعطانا كوز واحد تيك هوم …\nمتساعد فيهم، يخلي الطلاب هي الي تتفق وتحدد الوقت المناسب للكوز …\nيحذف اسوأ كوز …\nفي كويزين منهم كان فيها اسئلة بونص …\nو فيه كويز اونلاين عاده للطلاب الي يبي يعيدونه، واخذ افرج الكوزين …\n\nالمياجر :\nكومن …\n\nالفاينلات :\nكومن …\n\nالقريد النهائي :\nA ، انصح فيه …\n\nالصوت :\nواضح ومفهوم، بس مشكلته ينعس نوعاً ما اذا ماركزت معه …\n\nإضافات :\nانا اخذت الدكتور لأنهم كانوا يمدحوه بالتصحيح كثير، شخصياً ما شفت انه تصحيحه زي ما انوصف لي، توقعته يتساهل اكثر بمراحل، لكن فالنهاية تفاجأت بالقريد الي عطاني وياه، ابداً ما توقعت اجيب هالقريد نظراً لـ درجاتي صراحه …\n\nراح يكتب لكم بعض القوانين او الخطوات في السبوره، صورها واستفيد منها، مع مشاهدة الأونلاين كورس راح تفهم الكورس افضل وافضل …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492839-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/salem-bashmal/118645/10", "user": "m_shaer6", "ts": 1526917422000, "tid": 118645, "pn": 10}}]}', 1526917422000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10610-me201', 'stk-user10610', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f118645", "n": "Dr. Salem Bashmal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME201-192\nالتحضير:\nأول 5 دقايق في الكلاس , يفتح ملف أكسل ويحضر. تقدر تسوي ميك اب لكن تستاذن أول\nالشرح :\nيشرح من سلايدات الكتاب , موجودة على النت تقدر تبحث عنها وأحيانا يضيف من عنده سلايدات خارجية عشان توصل لك الفكرة أفضل. الدكتور ما شاء الله ملم بالمادة وفااهم وهو هادي بطبعه عشان كذا في الكلاس بيشرح لك بشويش فلو انك مصحصح وكذا بتفهم وامور تمام لكن لو فيك النوم بتنام بالراحة.\n- يجيب لك اسئلة كثير صعبة ويعلمك طريقة البداية فيها وخطوات الحل وانت تكمل لو تبغى تحلها ( يجيبها مثلا نهاية التشابتر وتكون شاملة كل الافكار) لكن ما يعطيك الحل بالتفصيل.\nكل درس يقسمة كلاسين يعني في الكلاس اليوم تكمل الدرس السابق وتبدا درس جديد والمقصد يقول لو غاب طالب ما يفوته شي كثير.\nالكوزات :\nبلاكبورد في الغالب يعطيك مثلا من 5 العصر الى 11 الليل تدخل تحل ووقت الكوز نص ساعه أما سؤال وتحل أو مجموعة اسئلة كونسبت. وأحيانا يعطيك تيك هوم كوز", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522089-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/salem-bashmal/118645/13", "user": "user10610", "ts": 1589630893000, "tid": 118645, "pn": 13}}]}', 1589630893000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9438-me201', 'stk-user9438', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f152767", "n": "Dr. Khaled Al-Athel", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور خالد العذل روووووووعه … شرح ممتاز وتصحيح يعطيك حقك وشديد في التحضير لكن يعتبر الطلاب عياله ويتعاون معهم … ويدف في الفاينال قرييييد ،، الماده الي خذت عنده me201 يعني صعبه شوي فتحتاج هذا النوع من الدكاتره", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1424261-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-al-athel/152767/4", "user": "user9438", "ts": 1439886714000, "tid": 152767, "pn": 4}}]}', 1439886714000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-muhanad_alhazmi-me201', 'stk-muhanad_alhazmi', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f172583", "n": "Dr. Mahmoud Khater", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 201 term 152\n\nالدكتور هذا اول ترم له\n\nما يحب التحضير يحضر مرة قليل لو طلب منه وجدا جدا متعاون ويراعي ظروفك بكل جدية ويثق في طلابه\n\nكان يشرح من سلايداته ويرفعها على البلاك بورد وكان كافية بالنسبة لي وكان يركز على ايش انت تحتاج ويناقش الطلاب ولو ماعرف يحل السؤال يعتذر منك يقول اروح اشوف كيف ينحل وارجع لكم الكلاس الجاي وكان عند كلمته\n\nاعطانا ثلاث كوزات وأخذ أحسن اثنين وكانت سهلة\n\nالمياجر كومون وتصحيحه كان روعة ما ينتظر انك تغلط اهم شئ انك فاهم ولا تغلط في الكونسبت لانه اهم شئ بالنسبة له\n\nالقريد النهائي\n+++++++++++++++++A\n\nالصوت واضح\n\nإضافات\nالدكتور شباب ومرة عسل ويحب الضحك ويكره يخليك تحمل هم باي طريقة\n\nدكتور محمود … الله يجمعني فيك بالجنة صراحة ما يتفوت", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1450388-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mahmoud-khater/172583/2", "user": "muhanad_alhazmi", "ts": 1464191302000, "tid": 172583, "pn": 2}}]}', 1464191302000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ksa1990-me201', 'stk-ksa1990', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f172583", "n": "Dr. Mahmoud Khater", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 201 - 162\nالتحضير : ما يحضر\nطريقة الشرح : الشرح فوق الممتاز يشرح الكونسبت بعدين يحل أمثلة عليها وشرحه كله بالعربي 🙂 والساعة عنده تمر كأنها ربع ساعة\nالكويزات : 3 كوزات طول الترم وكلها سهله\nالمياجر: كومون لكن تصحيحه للميجر جدا بطل لو الأرقام فيها أغلاط والبروسيجر صحيح يعطي درجة كامله مع إنه ميجر 🙂\nالفاينلات : كومون\nالقريد النهائي: A+++++++++\nالصوت: واضح جدا\nإضافات : الله يوفق هالدكتور دنيا واخره ويستاهل تخرب جدولك علشان تدرس عنده من الآخر هالدكتور اسطوووووورة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1471708-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mahmoud-khater/172583/4", "user": "ksa1990", "ts": 1492724240000, "tid": 172583, "pn": 4}}]}', 1492724240000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m.n.a-me201', 'stk-m.n.a', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f172583", "n": "Dr. Mahmoud Khater", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 201 - 162\nالتحضير : ما يحضر, طول الترم حضر مرة وحده بس وحط قبلها Announcement عى البلاك بورد\nطريقة الشرح : الشرح انا اشوفه عادي جدا واحيانا يجيب العيد في بعض المسائل ولكن الكونسبت الاساسي تفهمه منه زين\n\nالكويزات : 3 كوزات طول الترم وكلها سهله جدا واخذ احسن كويزين\n\nالمياجر: كومون لكن تصحيحه للميجر جدا جدتا بطل اهم شي عنده الكونسبت ما يهتم بالارقام ابدا لو الأرقام كلها غلط والبروسيجر صحيح يعطي درجة كامله ولو عندك خطا في جزئية ينقص عليها بس ويكمل عادي , ما شفت تصحيح احسن منه.\nالفاينلات : كومون\nالقريد النهائي: A+++++++++\nالصوت: واضح جدا. في بداية الترم سال اذا كان معنا غير عرب عشان شرحه تقريبا كله بالعربي و انجليزيته كمان ممتازة\nإضافات : الدكتور اخلاق جدا و طيب و متعاون مع الطلاب لابعد درجه متساهل في مواعيد الهومووك وزاد الكل 15% في درجة الهوموورك الكلاس وورك عنده شبه مضمون.\nفي ملاحظة بس انه بسبب التصحيح الكويس الافرج عنده يكون نسبيا عالي فلازم تشد حيلك .\n\nاخيرا انصح بالدكتور بشدة نزل عنده وانت مغمض.\nالله يوفقه ❤️ ما تشيل هم الداينمكس اللي هي اصعب مواد السفمور وانت عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474842-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mahmoud-khater/172583/5", "user": "M.N.A", "ts": 1497043524000, "tid": 172583, "pn": 5}}]}', 1497043524000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-anonymous16-me201', 'stk-anonymous16', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f175789", "n": "Dr. Jihad Alqasimi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "جهاد القاسمي ME 201 - T242\n\nالتحضير: واجد يشدد عالحضور والتأخير.\n\nطريقة الشرح: شرحه وسط، أحيانًا واضح وأحيانًا يضيع.\n\nالكويزات: صعبة والتصحيح سيء.\n\nالمياجر: التصحيح فيه شدة والدرجات أقل من اللي توقعت.\n\nالفاينلات: الاختبار كان كومن، بس طول واجد بالتصحيح.\n\nالقريد النهائي: D.\n\nالصوت: صوته مسموع.\n\nإضافات: يتأخر بالدرجات بشكل عام\n\nالأفرج كان اقل من باقي الدكاترة\n\nالقريدات سيئة\n\nلا انصح به", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1540306-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jihad-alqasimi/175789/4", "user": "anonymous16", "ts": 1756010377417, "tid": 175789, "pn": 4}}]}', 1756010377417, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abofordan2004-me201', 'stk-abofordan2004', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f182902", "n": "Dr. Nizar Jaber", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM 201 ONLINE\n\nME201\n\nالتحضير : كان عن طريق البلاكبورد بدون ما ينادي الاسماء يعني لو تفتح المحاضرة وتطلع خارج البيت ما درى عنك\n\nشرح : عن طريق السلايدات و للامانه شرحة جدا ممتاز وواضح يوصلك المعلومه على طول بدون فلسفة مدة الشرح تاخذ عشر دقايق او ربع ساعة بالكثير بعدها يبدا بالتمارين مباشرة\n\nبالنسبة للكويزات : عنده اثنين REVIEW QUIZ و ATTENTION QUIZ الريفيو كل اسبوعين والاتنشن كل اسبوع وكل واحد فيهم عليه 15% من القريد ويكون اخر 10 دقايق\n\nالميد والفاينل كومن وعباره عن كم سؤال كتابة وحدود 10 اسالة ملتبل تشويس\n\nالتصحيح : ما يمديك تحكم بحكم انه مشترك بين الاساتذه يعني كل واحد يصحح سؤال او فقرة\n\nمميزاته : جدا شريح ويرفع الريكوردينق بالبلاكبورد لكل محاضرة + اخلاقة جدا عالية ويحب الاسأله كثير ( ما يمل منها ابدا ) ويجاوبك حتى لو سؤالك تافه + صوته ولهجتة واضحين ويشرح لك بالانجليزي و يرد على الاسالة بالعربي\n\nملاحظة : تقييمي له بالاون لاين فقط , ممكن يكون الدكتور مختلف 180 درجه في الحضوري مثل غالبية الدكاتره", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526983-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nizar-jaber/182902/3", "user": "AboFordan2004", "ts": 1607331708000, "tid": 182902, "pn": 3}}]}', 1607331708000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sake-me201', 'stk-sake', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f182902", "n": "Dr. Nizar Jaber", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 201 - Term 201 Online\n\nالتحضير: عن طريق احصائيات البلاك بورد\nطريقة الشرح: يشرح من سلايدات القسم ، يقعد حول 10-15 دقيقة يشرح المفاهيم بشكل راقي وبعدها يحل سؤالين ثلاثة بتفصيل تام ومرتب\nبشكل عام يحل مسائل كثيرة منها تفهم المفاهيم بشكل افضل ، وفي محاضرات كثيرة خلاها فقط حل مسائل ، لو تركز وياه مابتحتاج تحل كثير للكويزات او المياجر\n\nالكويزات: في نوعين من الكويزات ، اتنشن وريفيو ، الاتنشن اسئلة مفاهيم وسهلة جدا والافرج فيها عالي ، الريفيو عبارة عن نسخ لصق من اسئلة الكتاب الفردية مع تغيير ارقام فقط ، ولكن لاحظت ببعض الاسئلة ان الدكتور مسهلها ، فمثلا الكتاب يحتاج منك اول تجيب inertia ثم تكمل ، الدكتور عطانا قيمتها بالسؤال. بخصوص الوقت يعطينا وقت كافي ، الاتنشن 10 دقائق لأربعة اسئلة بدون باك تراكنق ، والريفيوز بالبدايات 20 دقيقة لثلاث اسئلة بعدين خلاها 30 دقيقة لسؤالين بس!!! يقول ركز بالحل وارجوك اطلع بالجواب الصح ، وطبعا الريفيو في باك تراكنق ، جدا متعاون بالكويزات\n\nالمياجر/الفاينلات: كومن\nالصوت: واضح وطول الوقت يتكلم انجليزي بلهجة واضحة جدا\n\nإضافات: اخلاقه جددداا عالية ورائعة ، يهمه كثيرا مصلحة الطالب ودائما يجاوب عالاسئلة ، متواجد دائما بالساعات المكتبية وماعنده مشكلة ياخذ وقت زيادة عشان مصلحتك ، لاتتردد ابدا بالتسجيل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527909-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nizar-jaber/182902/5", "user": "SAKE", "ts": 1610786487000, "tid": 182902, "pn": 5}}]}', 1610786487000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-anon63725347-me201', 'stk-anon63725347', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f185187", "n": "Dr. Mustafa Al Shaqaq", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 201 - TERM 231\nد: مصطفى الشقاق\n\n● التحضير :\nمتساهل في التحضير، ورقة تمر على الطلاب في نهاية الكلاس، وما يدقق على التأخير\n\n● الشرح :\nمتوسط، يشرح من سلايدات الكتاب ويحاول يحل اكبر عدد من الاسئلة، لو تركز معه رح تفهم نوعا ما.\n\n● الكويزات:\nمستواها متفاوت مرات سهله ومرات صعبة، لكنه متعاون من ناحية تحديد موعد الكويز والمتيريل.\n\n● التصحيح:\nعسسسسل من ناحية التصحيح، ما يخصم واجد على الاخطاء ويحاول يزود على اي خطوة أو فورملا تكتبها.\n\n● التعامل:\nالدكتور عسل وراقي من ناحية التعامل، ودايما يحب يراعي الطلاب في مواعيد الكويزات، وما يدقق على الجوال في الكلاس ويعطيك الحرية الكاملة في الكلاس.\n\nانصح وبشده بالتسجيل عند الدكتور مصطفى", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1537205-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mustafa-al-shaqaq/185187/2", "user": "anon63725347", "ts": 1704797774000, "tid": 185187, "pn": 2}}]}', 1704797774000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-husain_q98-me201', 'stk-husain_q98', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f187902", "n": "Dr. Ammar Alzaydi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم – ME 201 - 212\n\nالحضور:\n\nخلال الترم، الدكتور ما كان يتواجد وايد، والمحاضرات اللي حضرها تقريباً ما توصل عشرين. وقت التحضير، كان أحياناً يتجاوز أسامي بعض الطلاب اللي يعرفهم… هل له ظرف؟ سبب؟ ما ندري، وما نقدر نحكم.\n\nوفي الإيميل الأخير ذكر إن في طالب رسب، واللي نسمعه بين الطلاب إن السبب الغياب، بس هو ما ذكر هالكلام.\n\nطريقة الشرح:\n\nطريقة شرحه ما تناسب طبيعة المادة. المادة تعتمد على حل المسائل خطوة بخطوة، وهو يمرّ عليها مرور سريع ويقول: “I will leave it to you”. يعرض مقاطع تشرح الفكرة العامة، بس ما تغطي جانب الحل اللي يحتاجه الطالب.\n\nالكويزات:\n\nالكويزات نفس السلايدات، بس محوّلة خيارات، وغالباً الخيار الأول يكون هو الصح. وبسبب اختلاف أوقات السكاشن، الطلاب اللي يختبرون بعد تصير عندهم فكرة واضحة عن نوعية الأسئلة لأن اللي قبلهم يختبرون أول والمعلومات تنتقل بسرعة.\n\nأنا كنت في سكشن 8، وسكشن 10 بعدنا، وكل شي كان يوصل في القروب\n\nالمياجر:\n\nالاختبار Common، وتصحيحه حقّاني وبالمسطرة\n\nالفاينل:\n\nنفس نمط المياجر، ما تغيّر شيء.\n\nالقريد النهائي:\n\nF\n\nالصوت:\n\nالصوت شوي منخفض، بس الإنجليزي واضح .\n\nإضافات:\n\nالدكتور اذا حضر عادة يطفي الأنوار وقت الشرح ويتحرّك بالكلاس، ويركّز على شرح الفكرة العامة بدون ما يحل المسائل، وهذا الشي ما يفيد مادة تعتمد أساساً على الحل.\n\nوكان يرسل انه مضطر يغيب لاسباب متنوعه اغلبها لها علاقه بحمل وولادة زوجته\n\nوبنهاية الترم، أرسل إيميل قال فيه إن الأفريج 2.69/4 وأعلى أفريج بتاريخ المادة. بينما بنفس الترم وقبله، في دكاترة أفريجاتهم أعلى وشرحهم أفضل، بدون ما يتكلمون عن الموضوع بهالأسلوب.\n\nنصيحة:\n\nمن واقع التجربة… ما أنصح تنزل مادة معه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1540610-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ammar-alzaydi/187902/2", "user": "husain_q98", "ts": 1654590112000, "tid": 187902, "pn": 2}}]}', 1654590112000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-papercomet-me201', 'stk-papercomet', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f187902", "n": "Dr. Ammar Alzaydi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المقرر والترم الدراسي: ME201 252\n\nالتحضير\nالدكتور يلغي محاضرات واجد، والتحضير عنده بس ينادي الأسامي ويسجل الحضور.\n\nولما القسم صاده يلغي كلاسات كثيرة، أرسل لنا إيميل يتكلم فيه عن أهمية الحضور، وإنه ملاحظ كثرة غياباتنا، وإنه يشرح بالكلاس أشياء مهمة ومفيدة وأشياء صعبة تجي بالاختبارات، مع إن الواقع عكس هالكلام تمامًا!\n\nوالأغرب إنه بعد ما صاده القسم، صار يجي بالكلاس ويعلمنا إن المحاضرة الجاية ملغية، أو إن الحضور بس للي يبي يعوض كوز!\n\nالشرح والتعامل\nشرحه سيئ جدًا، وواضح إنه ضايع ومو فاهم المادة بالشكل المطلوب. مرة جاء ومعاه ورقة ينقل منها مثال، ومع هذا شرح إن الرمز rho يعني الكثافة (Density)، مع إن المقصود فيه كان نصف قطر الانحناء (Radius of Curvature) 😦\n\nوأغلب الكلاسات اللي يحضرها يقعد يقرأ السلايدات قراءة بدون شرح فعلي. حاول كم مرة يجيب ورقة وينقل منها، بس حتى بهالطريقة ضاع وبطل.\n\nوبالتعامل يحاول يكون فرندلي بردوده، بس بالواقع يقعد يصرفك في أغلب الأمور، وأحيانًا يتأخر بالرد. يعني أسلوبه بالكلام زين، بس إذا احتجت منه شيء أو توضيح ما تستفيد بالشكل المطلوب.\n\nأعمال السنة\nالواجبات كانت تتأجل من الكورد، وكان الدكتور يجي يتمنن علينا بالتأجيل وكأنه هو اللي سعى فيه، مع إن خبر التأجيل كان واصلنا من بدري، وما كان له دخل فيه. بس سلك تعش تنتعش!\n\nوكان يستغل موضوع تأجيل الواجبات ويذكرنا فيه كأنه مسوي لنا معروف كبير، خصوصًا مع موضوع التقييم.\n\nالاختبارات\nالكويزات كانت خيارات، وغالبًا الخيار الأول هو الإجابة الصح، والأسئلة منسوخة من السلايدات.\n\nأما المياجر، فكان يعطي درجات عالية بشكل غريب. عادي يكون حلك كله صح وخويك حله كله غلط، وبالنهاية الفرق بينكم خمس درجات بس!\n\nوبالنسبة للفاينل، نزل درجات الاختبار وبنفس الوقت حط اللتر قريد بالتطبيق مباشرة، وما أعطانا أي مجال نراجع درجاتنا أو نناقش التصحيح معاه.\n\nوالغريب إن رغم تساهله الظاهر بالتصحيح والكويزات، ما طلع من السكشنين إلا طالب واحد جاب A+.\n\nإضافات\nالدكتور كان ضاغط علينا بشكل مو طبيعي عشان نعطيه تقييم عالي. وكل شوي يتمنن بالكويزات السهلة، والتصحيح، وتأجيل الواجبات، ويوعدنا بقريدات زينة. وللأسف صدقناه، مع إن النصيحة اللي وصلتنا من طلابه بالمشين كانت إننا نعطيه تقييمه الحقيقي وما ننخدع بهالأشياء.\n\nالدكتور يسوي كل شيء عشان يتفادى الشرح والحضور، وللأسف هالشيء ينعكس بشكل سلبي على مستوى الطالب وفهمه وحماسه للمقرر. وحتى سالفة إيميله عن أهمية الحضور بعد ما صاده القسم كانت مستفزة، خصوصًا إنه بعدها صار يجي بالكلاس ويقول إن المحاضرة الجاية ملغية أو إن الحضور بس للي يبي يعوض كوز!\n\nالمقرر يحتاج دكتور يشرح ويجتهد ويشجعك إنك تجتهد معاه، مو دكتور يخليك تستانس بإلغاء المحاضرات والكويزات السهلة، وبالنهاية تكتشف إنك ما استفدت من المادة ولا من درجاتك بالشكل اللي كنت تتوقعه.\n\nولا تستانس إذا الدكتور يكنسل كلاسات واجد أو يسهل الكويزات، لأن هالأشياء بالنهاية بتنقلب ضدك مو لصالحك، خصوصًا إذا ما فهمت المادة زين وما قدرت حتى تراجع درجاتك معاه.\n\nإحنا من الأساس ما نزلنا عنده باختيارنا، لكن حولونا عليه. ولو يرجع فيني الزمن، والله لأروح أحاجج وأطالب يرجعوني لسكشني السابق بدل ما أكمل معاه.\n\nالتجربة أبدًا ما تسوى، ونصيحتي لا تنخدع بالتسهيلات والوعود. قيّم الدكتور على شرحه وحضوره وتعامله وتعلّمك الفعلي من المادة، مو على عدد الكلاسات اللي يلغيها أو الكويزات السهلة اللي يعطيك إياها.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1541892-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ammar-alzaydi/187902/22", "user": "papercomet", "ts": 1779257160000, "tid": 187902, "pn": 22}}]}', 1779257160000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-harborlantern-me201', 'stk-harborlantern', 'ME 201', 'doc', '{"docs": [{"id": "stk-dr-f187902", "n": "Dr. Ammar Alzaydi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المقرر والترم الدراسي: ME201 252\n\nالتحضير\nمحاضرات الدكتور يغيب عنها كثير، ويلغيها بشكل متكرر، وحتى المحاضرات اللي يحضرها غالبًا ما يكون محضر لها بالشكل المطلوب. الوقت المخصص للمادة ما يُستغل بشكل يفيد الطالب.\n\nالشرح والتعامل\nللأسف شرحه سيئ جدًا، وواضح إنه مو متمكن من المادة ولا فاهم المجال بالشكل المطلوب. أحيانًا وهو يشرح تحسه كأنه يرقص من كثر ما هو ضايع ومو عارف كيف يوصل المعلومة، ويقعد يتنقل بين الكلام والسلايدات بدون شرح واضح. وفوق هذا يتضجر من تدريس المادة وكأنه مغصوب عليها.\n\nأما تعامله، فالمشكلة الأكبر هي التمنن. أي تواصل معاه يحاول يطلع منه بصورة إنه ساعدك وفزع لك وسوى لك معروف كبير، حتى لو ما قدم أي مساعدة فعلية. يحاول يكون ودود بالكلام، لكن بالنهاية ما تطلع منه بفائدة واضحة.\n\nأعمال السنة\nطوال الترم كانت الواجبات والتأجيلات من أكثر الأشياء اللي يتمنن فيها، ويصورها كأنها بجهوده الشخصية، مع إن بعضها أساسًا من الكورد وما له فضل فيها. بدل ما يركز على شرح المادة ومساعدة الطلاب على فهمها، كان يكرر الكلام عن التسهيلات اللي يقدمها.\n\nالاختبارات\nشملت الاختبارات كويزات سهلة، وكان التصحيح في بعض الاختبارات متساهل، لكن هذا ما يعوض ضعف الشرح. أما الفاينل، فنزل درجاته واللتر قريد بنفس الوقت مباشرة، وكانت القريدات سيئة جدًا، وما أعطى الطلاب مجال لمراجعة درجات الفاينل قبل نزول القريد النهائي، ومراجعة الدرجات مع الدكتور كانت مهمة مستحيلة. وبالنهاية النتائج ما كانت مثل الوعود والتوقعات اللي يعطيها.\n\nإضافات\nهنا أتفق مع كثير من الكلام المذكور بالتقييم السابق. الدكتور يكثر من إلغاء المحاضرات، وشرحه ضعيف، وفوق هذا يتمنن بشكل مبالغ فيه بأي تسهيل أو تواصل، ويحاول يحسسك إنه وقف معك وساعدك حتى لو الموضوع ما يستاهل أو ما كان له دور فيه أصلًا.\n\nوكان يضغط باتجاه إعطائه تقييمات عالية، ويذكر باستمرار تساهله بالكويزات والتصحيح والتأجيلات وكأنها خدمات تستوجب الشكر والتقييم المرتفع.\n\nالمشكلة إن كثرة الإلغاءات والتسهيلات ممكن تريحك مؤقتًا، لكنها بالنهاية تأثر على فهمك ومستواك بالمادة. الدكتور المفروض يشجعك على التعلم والاجتهاد، مو يخليك تحس إنه متضايق من تدريس المقرر.\n\nأنصح مثل ما ذكر التقييم السابق إنكم تقيمونه بحق، على حضوره وشرحه وتعامله والفائدة اللي حصلتوها من المادة، مو على التسهيلات والوعود. بالنهاية التقييم أمانة.\n\nومن كثر سوء تجربتي مع الدكتور، وبعد ما خالف وعوده بخصوص التقييم والقريدات، قررت أفتح حساب بالمنتدى خصيصًا عشان أكتب تجربتي معاه وأنبّه الطلاب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1541893-me201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ammar-alzaydi/187902/23", "user": "harborlantern", "ts": 1781255820000, "tid": 187902, "pn": 23}}]}', 1781255820000, 1794826867, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
